INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(161, 'Pengulas Sukan', 'Pengulas sukan muda yang suara lantangnya memenuhi stadium (watak rekaan).', 'Menyampaikan kejayaan sukan negara kepada peminat.', 'jejaka_melayu.png'),
(162, 'Jurulatih Sekolah', 'Jurulatih yang melatih atlet muda di sekolah dengan semangat tinggi (watak rekaan).', 'Membimbing murid mengenali atlet dan program sukan negara.', 'jejaka_india.png'),
(163, 'Murid Peminat Sukan', 'Murid yang mengumpul kad dan keratan akhbar tentang atlet negara (watak rekaan).', 'Menyimpan kisah kebanggaan sukan negara dalam buku skrapnya.', 'budak_gajet.png'),
