INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(901, 'Siaran Langsung Stadium Kebanggaan Negara', 9, 'Masuki peranan pengulas sukan yang membuat siaran langsung dari stadium ke stadium. Kau mengenali persatuan sukan, pencapaian badminton, bola sepak, olahraga dan hoki serta legenda sukan terdahulu.'),
(902, 'Latihan Pagi Jurulatih Sekolah', 9, 'Masuki peranan jurulatih sekolah yang melatih murid di padang, trek dan dewan. Kau mengenali atlet kebanggaan negara, atlet paralimpik, e-sukan dan faedah penganjuran sukan antarabangsa.'),
(903, 'Buku Skrap Peminat Sukan Negara', 9, 'Masuki peranan murid peminat sukan yang mengumpul kad dan keratan akhbar. Dalam buku skrapmu kau menyimpan program sukan perpaduan, penganjuran sukan antarabangsa dan tokoh inspirasi sukan negara.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e9_n1_s1', 'Dewan badminton. Papan skor menunjukkan nama Persatuan Badminton Malaysia, tetapi nota pengulas terselit di bawah kerusi dan mengelirukan.', 1, 901, 'badminton.png'),
('e9_n1_s2', 'Siaran ulangan perlawanan Piala Thomas. Seorang peminat bertanya apakah pencapaian antarabangsa badminton negara, dan mengaku sering keliru antara kejohanan.', 2, 901, 'piala_thomas.png'),
('e9_n1_s3', 'Stadium bola sepak. FAM menganjurkan liga, tetapi kad catatan pengulas terkoyak dan nama pasukan serta tahun bercampur.', 3, 901, 'bola_sepak.png'),
('e9_n1_s4', 'Peminat muda menunjukkan video gol jarak jauh. Dia bertanya sama ada pemain negara pernah mendapat anugerah dunia, dan berhujah gol itu tidak mungkin pernah menang apa-apa di peringkat dunia.', 4, 901, 'bola_sepak.png'),
('e9_n1_s5', 'Trek olahraga lama. Rakaman pecut tahun 1966 dan 1982 diputar. Pengulas mahu empat bukti bahawa atlet negara pernah memenangi emas 100 meter Sukan Asia.', 5, 901, 'olahraga.png'),
('e9_n1_s6', 'Pejabat KOM. Seorang peminat menanyakan sejarah KOM dan pencapaian terbaru atlet olahraga. Beberapa borang catatan bertukar-tukar.', 6, 901, 'olahraga.png'),
('e9_n1_s7', 'Padang hoki. Peminat sedang memperdebatkan kedudukan pasukan hoki negara dalam Piala Dunia. Papan kenyataan MHC tergantung senget.', 7, 901, 'hoki.png'),
('e9_n1_s8', 'Dinding galeri sukan. Empat legenda terdahulu berdiri dalam bingkai. Pengulas mahu gelaran dan pencapaian mereka dipadankan.', 8, 901, 'semua_podium_sukan.png'),
('e9_n2_s1', 'Dewan sekolah sebelum perhimpunan. Papan podium dipenuhi gambar pingat dan bendera. Murid bertanya bukti bahawa pencapaian atlet melambangkan kebanggaan negara.', 1, 902, 'semua_podium_sukan.png'),
('e9_n2_s2', 'Gelanggang badminton sekolah. Poster Lee Chong Wei tergantung di dinding. Murid mengaku keliru tentang anugerah dan gelaran yang pernah dimenangi beliau.', 2, 902, 'badminton.png'),
('e9_n2_s3', 'Dinding galeri atlet. Tiga poster Nicol Ann David, Pandelela Rinong dan Azizulhasni Awang tergantung terbalik. Murid diminta membetulkan gelaran dan pencapaian mereka.', 3, 902, 'sukan_komanwel.png'),
('e9_n2_s4', 'Padang hoki sekolah. Murid memegang kad S. Kuhan tetapi tidak pasti rekod pemain itu. Kad bercampur dengan rekod atlet lain.', 4, 902, 'hoki.png'),
('e9_n2_s5', 'Kolam renang sekolah. Murid mahu tahu berapa banyak pingat emas yang dimenangi Nurul Huda dan sejauh mana Abdul Malek mengharumkan nama negara.', 5, 902, 'sukan_sea.png'),
('e9_n2_s6', 'Seorang murid menunjukkan telefon dan bertanya sama ada permainan video boleh dianggap sukan. Cikgu menunjukkan satu kad e-sukan negara.', 6, 902, 'semua_podium_sukan.png'),
('e9_n2_s7', 'Perhimpunan sekolah. Empat atlet paralimpik muncul dalam bentuk poster di dinding dewan. Murid ingin tahu pencapaian setiap atlet, dan guru meminta mereka dipadankan.', 7, 902, 'sukan_alat_perpaduan_dan_keharmonian_kaum.png'),
('e9_n2_s8', 'Bilik guru. Pengetua bertanya faedah negara menjadi tuan rumah sukan antarabangsa. Kad kenyataan bertaburan di atas meja.', 8, 902, 'sukan_komanwel.png'),
('e9_n3_s1', 'Halaman pertama buku skrap, iaitu enam program sukan perpaduan. Keratan bercampur, dan tarikh serta fungsi tidak jelas.', 1, 903, 'sukan_alat_perpaduan_dan_keharmonian_kaum.png'),
('e9_n3_s2', 'Keratan akhbar SUKMA. Murid meragui bahawa ada temasya yang lebih besar daripada kejohanan sekolah. Cikgu bertanya temasya sukan terbesar dalam negara.', 2, 903, 'sukan_alat_perpaduan_dan_keharmonian_kaum.png'),
('e9_n3_s3', 'Halaman Sukan SEA dalam buku skrap. Cikgu mahu murid menyusun peristiwa penting penganjuran Sukan SEA.', 3, 903, 'sukan_sea.png'),
('e9_n3_s4', 'Halaman Piala Thomas dan Hoki Piala Dunia. Dua senarai tahun bercampur. Murid perlu membezakan tempat dan tahun penganjuran.', 4, 903, 'piala_thomas.png'),
('e9_n3_s5', 'Halaman sukan antarabangsa lain, iaitu permotoran, Le Tour de Langkawi, Komanwel, Formula One dan Piala Monsun. Enam keratan terlepas daripada kategorinya.', 5, 903, 'le_tour_de_langkawi.png'),
('e9_n3_s6', 'Halaman Komanwel. Murid terjumpa dua gambar maskot dan logo. Dia ragu sama ada maskot itu singa atau orang utan.', 6, 903, 'sukan_komanwel.png'),
('e9_n3_s7', 'Halaman kesimpulan. Cikgu meminta murid menulis cinta akan negara pada tiga peringkat, iaitu diri, masyarakat dan negara.', 7, 903, 'semua_podium_sukan.png'),
('e9_n3_s8', 'Halaman terakhir. Tiga pemimpin sukan negara muncul dalam keratan, iaitu seorang Sultan, seorang setiausaha agung bola sepak dan seorang bekas atlet polo air. Murid perlu memadankan jawatan dan sumbangan mereka.', 8, 903, 'semua_podium_sukan.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(901, 'e9_n1_s1', 'Persatuan Badminton Malaysia', 'Padankan butiran Persatuan Badminton Malaysia (BAM) dengan maklumatnya.', '4', 'Memahami BAM: ditubuhkan 1960; menganjurkan Kejohanan Badminton Kebangsaan; melahirkan atlet seperti Punch Gunalan, Misbun Sidek dan Lee Chong Wei.', '{"pairs": [{"text": "BAM ditubuhkan pada tahun", "pair": 1}, {"text": "1960", "pair": 1}, {"text": "Kejohanan yang dianjurkan BAM", "pair": 2}, {"text": "Kejohanan Badminton Kebangsaan", "pair": 2}, {"text": "Atlet kebanggaan yang dilahirkan", "pair": 3}, {"text": "Punch Gunalan, Misbun Sidek dan Lee Chong Wei", "pair": 3}, {"text": "Pencapaian antarabangsa", "pair": 4}, {"text": "Juara Piala Thomas lima kali dan pingat Olimpik", "pair": 4}], "aftermath": "Butiran bertukar dan siaran menyatakan BAM ditubuhkan pada tahun 1963. Peminat menegur.", "turns": [{"after": 5, "options": [{"text": "Persatuan sukan membangunkan atlet dan mengharumkan nama negara.", "isCorrect": true, "reaction": "Betul. Siaran bermula dengan lancar."}, {"text": "Sebenarnya, persatuan sukan tidak diperlukan kerana atlet berlatih sendiri.", "isCorrect": false, "reaction": "Pengulas menggeleng. Persatuan menganjurkan kejohanan dan melahirkan atlet."}, {"text": "BAM memajukan sukan bola sepak, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Itu peranan FAM. BAM memajukan badminton."}], "clue": "Persatuan membangunkan atlet."}]}'),
(902, 'e9_n1_s2', 'Nota Pencapaian Badminton', 'Baca nota dan tentukan pencapaian badminton negara pada peringkat antarabangsa.', '5', 'Memahami pencapaian badminton: juara Piala Thomas lima kali; pingat perak dan gangsa Sukan Olimpik; juara All England bagi acara beregu dan individu lelaki.', '{"clueText": "Nota: Pencapaian sukan badminton negara cemerlang pada peringkat antarabangsa. Atlet negara muncul juara sebanyak lima kali Kejohanan Piala Thomas dan memenangi pingat perak dan gangsa Sukan Olimpik. Mereka juga pernah menjuarai Kejohanan Badminton Terbuka All England bagi acara beregu dan individu lelaki.", "options": [{"text": "Juara Piala Thomas lima kali dan pemenang pingat perak serta gangsa Olimpik.", "isCorrect": true}, {"text": "Juara Piala Dunia Hoki dan pingat emas Olimpik.", "isCorrect": false, "consequence": "Itu tidak betul. Nota menyebut Piala Thomas dan pingat perak serta gangsa Olimpik."}, {"text": "Juara Piala Suzuki AFF dan Sukan SEA.", "isCorrect": false, "consequence": "Itu pencapaian bola sepak."}, {"text": "Juara Sukan Komanwel 1998 sahaja.", "isCorrect": false, "consequence": "Nota tidak menyebut perkara itu."}], "aftermath": "Nota tersalah baca dan siaran menyatakan Malaysia pemenang pingat emas Olimpik badminton. Peminat marah.", "turns": [{"after": 5, "options": [{"text": "Kita harus bangga dengan kejayaan badminton negara.", "isCorrect": true, "reaction": "Betul. Peminat bertepuk tangan."}, {"text": "Badminton negara tidak pernah menang di peringkat antarabangsa.", "isCorrect": false, "reaction": "Peminat membantah dengan nota di tangan."}, {"text": "Menurut aku, kejayaan badminton hanya diraih oleh satu kaum.", "isCorrect": false, "reaction": "Atlet pelbagai kaum menyumbang kejayaan."}], "clue": "Banggakan kejayaan badminton."}]}'),
(903, 'e9_n1_s3', 'Persatuan Bola Sepak Malaysia', 'Padankan butiran Persatuan Bola Sepak Malaysia (FAM) dengan maklumatnya.', '4', 'Memahami FAM: ditubuhkan 1963; menganjurkan Liga Malaysia; pemain Soh Chin Ann, James Wong, Safawi Rasid; Olimpik Munich 1972 dan Moscow 1980; Piala Suzuki AFF 2010.', '{"pairs": [{"text": "FAM ditubuhkan pada tahun", "pair": 1}, {"text": "1963", "pair": 1}, {"text": "Pertandingan yang dianjurkan FAM", "pair": 2}, {"text": "Liga Bola Sepak Malaysia", "pair": 2}, {"text": "Pemain berbakat", "pair": 3}, {"text": "Soh Chin Ann, James Wong dan Safawi Rasid", "pair": 3}, {"text": "Layak ke Sukan Olimpik", "pair": 4}, {"text": "Munich 1972 dan Moscow 1980", "pair": 4}, {"text": "Juara Piala Suzuki AFF", "pair": 5}, {"text": "Tahun 2010", "pair": 5}], "aftermath": "Butiran bertukar dan siaran menyatakan Malaysia layak ke Olimpik 1960. Peminat menegur.", "turns": [{"after": 5, "options": [{"text": "Bagi aku, pemain berbakat dilahirkan melalui liga yang teratur.", "isCorrect": true, "reaction": "Betul. Peminat bersorak."}, {"text": "Pemain berbakat tidak memerlukan liga, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Pengulas membetulkan. Liga melahirkan pemain."}, {"text": "FAM ditubuhkan pada tahun 1952, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Tahun itu ialah tahun penubuhan KOAM."}], "clue": "Liga melahirkan pemain."}]}'),
(904, 'e9_n1_s4', 'Nota Anugerah PUSKAS FIFA', 'Baca nota dan tentukan anugerah antarabangsa yang pernah dimenangi pemain Malaysia.', '5', 'Memahami bahawa Mohd Faiz Subri, ketika menjadi pemain pasukan Pulau Pinang, memenangi anugerah antarabangsa PUSKAS FIFA 2016.', '{"clueText": "Nota: Mohd Faiz Subri ketika menjadi pemain bola sepak pasukan Pulau Pinang pernah memenangi anugerah antarabangsa PUSKAS FIFA 2016.", "options": [{"text": "Anugerah PUSKAS FIFA 2016.", "isCorrect": true}, {"text": "Anugerah Pemain Lelaki Terbaik BWF.", "isCorrect": false, "consequence": "Itu anugerah yang diberikan kepada Lee Chong Wei."}, {"text": "Anugerah Atlet Terunggul Sepanjang Zaman Sukan Dunia 2021.", "isCorrect": false, "consequence": "Itu anugerah Nicol Ann David."}, {"text": "Anugerah Olahragawan Negara 1986.", "isCorrect": false, "consequence": "Itu anugerah Abdul Malek Mohamed Noor."}], "aftermath": "Nota tersalah baca dan peminat muda terus tidak percaya pemain negara boleh berjaya.", "turns": [{"after": 5, "options": [{"text": "Aku fikir pemain negara juga mampu berjaya di peringkat antarabangsa.", "isCorrect": true, "reaction": "Betul. Aku minta maaf."}, {"text": "Pemain negara tidak mampu menang anugerah dunia, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Nota menunjukkan sebaliknya."}, {"text": "Anugerah itu diraih oleh pemain badminton, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Itu salah. Anugerah itu untuk pemain bola sepak."}], "clue": "Pemain negara mampu ke peringkat dunia."}]}'),
(905, 'e9_n1_s5', 'Cari Bukti Pecut Sukan Asia', 'Cari empat bukti kejayaan olahraga negara dalam rakaman.', '2', 'Memahami bahawa atlet negara memenangi pingat emas acara 100 meter Sukan Asia pada tahun 1966 dan 1982; olahraga dikembangkan oleh KOAM (kini KOM).', '{"bgImage": "../assets/gameAsset/background/olahraga.png", "hotspots": [{"name": "Pelari pecut: pingat emas 100m Sukan Asia pada 1966 dan 1982", "top": "45.7%", "left": "47.5%"}, {"name": "Blok permulaan: acara 100m Sukan Asia", "top": "77.2%", "left": "54.5%"}, {"name": "Pegawai berjam randik: pengurusan olahraga oleh KOM", "top": "60%", "left": "14.5%"}, {"name": "Pelari kedua: atlet olahraga Malaysia dalam Kejohanan Sukan SEA", "top": "50.5%", "left": "70.8%"}], "aftermath": "Bukti tidak ditemui dan peminat menyangka atlet olahraga negara tidak pernah menang di Sukan Asia.", "turns": [{"after": 5, "options": [{"text": "Kejayaan olahraga hasil usaha atlet dan persatuan sukan.", "isCorrect": true, "reaction": "Betul. Rakaman ini bukti sejarah."}, {"text": "Pada pendapat aku, kejayaan olahraga hanya berlaku secara kebetulan.", "isCorrect": false, "reaction": "Pengulas membantah. Kejayaan itu hasil latihan dan organisasi."}, {"text": "Atlet olahraga tidak pernah menang di Sukan Asia.", "isCorrect": false, "reaction": "Rakaman menunjukkan emas 100 meter pada 1966 dan 1982."}], "clue": "Kejayaan hasil usaha."}]}'),
(906, 'e9_n1_s6', 'Nota Kesatuan Olahraga', 'Baca nota dan tentukan maklumat Kesatuan Olahraga Amatur Malaysia (KOAM).', '5', 'Memahami KOAM: ditubuhkan 1952, kini KOM; menganjurkan Kejohanan Olahraga Kebangsaan; atlet Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek; juara Sukan SEA 2017 dengan lapan emas.', '{"clueText": "Nota: Kesatuan Olahraga Amatur Malaysia (KOAM) ditubuhkan pada tahun 1952 dan kini dikenali sebagai Kesatuan Olahraga Malaysia (KOM). KOM menganjurkan Kejohanan Olahraga Kebangsaan. Atlet seperti Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek dilahirkan, dan atlet olahraga membantu negara muncul sebagai juara Kejohanan Sukan SEA 2017 dengan menyumbang lapan pingat emas.", "options": [{"text": "KOAM ditubuhkan 1952; kini KOM; juara Sukan SEA 2017 dengan lapan emas.", "isCorrect": true}, {"text": "KOAM ditubuhkan 1960; kini BAM; juara Sukan SEA 2017 dengan dua emas.", "isCorrect": false, "consequence": "BAM ialah persatuan badminton. Nota menyebut 1952 dan KOM."}, {"text": "KOAM ditubuhkan 1963; kini FAM; juara Sukan SEA 2017 dengan lapan emas.", "isCorrect": false, "consequence": "FAM ialah persatuan bola sepak."}, {"text": "KOAM ditubuhkan 1953; kini MHC; juara Sukan SEA 2017 dengan lapan emas.", "isCorrect": false, "consequence": "MHC ialah konfederasi hoki."}], "aftermath": "Nota tersalah baca dan siaran menamakan KOAM sebagai persatuan badminton. Peminat marah.", "turns": [{"after": 5, "options": [{"text": "Persatuan sukan sentiasa menyokong atlet daripada pelbagai kaum.", "isCorrect": true, "reaction": "Betul. Siaran bersambung."}, {"text": "Aku fikir persatuan sukan hanya menyokong satu kaum.", "isCorrect": false, "reaction": "Atlet pelbagai kaum dilahirkan."}, {"text": "Aku fikir persatuan sukan tidak menganjurkan kejohanan, jadi lupakan sahaja.", "isCorrect": false, "reaction": "KOM menganjurkan Kejohanan Olahraga Kebangsaan."}], "clue": "Atlet pelbagai kaum."}]}'),
(907, 'e9_n1_s7', 'Konfederasi Hoki Malaysia', 'Padankan butiran Konfederasi Hoki Malaysia (MHC) dengan maklumatnya.', '4', 'Memahami MHC: ditubuhkan 1953; Liga Hoki Kebangsaan; pemain Poon Fook Loke, Sarjit Singh, Mirnawan Nawawi; layak lapan kali Piala Dunia; tempat keempat 1975; naib juara Komanwel 1998.', '{"pairs": [{"text": "MHC ditubuhkan pada tahun", "pair": 1}, {"text": "1953", "pair": 1}, {"text": "Pertandingan yang dianjurkan", "pair": 2}, {"text": "Liga Hoki Kebangsaan", "pair": 2}, {"text": "Pemain hoki berbakat", "pair": 3}, {"text": "Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi", "pair": 3}, {"text": "Layak ke Hoki Piala Dunia", "pair": 4}, {"text": "Sebanyak lapan kali", "pair": 4}, {"text": "Tempat keempat Hoki Piala Dunia", "pair": 5}, {"text": "Tahun 1975", "pair": 5}, {"text": "Naib juara Sukan Komanwel", "pair": 6}, {"text": "Tahun 1998", "pair": 6}], "aftermath": "Butiran bertukar dan siaran menyatakan hoki negara tidak pernah layak ke Piala Dunia.", "turns": [{"after": 6, "options": [{"text": "Kejayaan hoki mengharumkan nama negara.", "isCorrect": true, "reaction": "Betul. Peminat bertepuk tangan."}, {"text": "Hoki negara tidak pernah mencapai kejayaan antarabangsa.", "isCorrect": false, "reaction": "Peminat menunjukkan rekod 1975 dan 1998."}, {"text": "Hoki negara hanya popular di sekolah.", "isCorrect": false, "reaction": "Pasukan negara pernah layak lapan kali ke Piala Dunia."}], "clue": "Banggakan kejayaan hoki."}]}'),
(908, 'e9_n1_s8', 'Empat Legenda Sukan', 'Padankan legenda sukan dengan pencapaiannya.', '4', 'Mengenal pasti tokoh terdahulu: Dr. M. Jegathesan (Manusia Terpantas Asia; tiga emas Sukan Asia 1966), M. Rajamani (olahraga wanita; Olimpik 1964), Tan Aik Huang (juara All England 1966), Mokhtar Dahari (Supermokh; 167 penampilan, 89 gol).', '{"pairs": [{"text": "Dr. M. Jegathesan", "pair": 1}, {"text": "Manusia Terpantas Asia; tiga emas Sukan Asia Bangkok 1966", "pair": 1}, {"text": "M. Rajamani", "pair": 2}, {"text": "Atlet olahraga wanita; mewakili negara di Olimpik 1964", "pair": 2}, {"text": "Tan Aik Huang", "pair": 3}, {"text": "Juara perseorangan lelaki All England 1966", "pair": 3}, {"text": "Mokhtar Dahari", "pair": 4}, {"text": "Digelar Supermokh; 167 penampilan antarabangsa dan 89 gol", "pair": 4}], "aftermath": "Legenda bertukar bingkai dan galeri memaparkan gelaran yang salah. Peminat mengeluh.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, kita perlu menghargai jasa atlet terdahulu yang terdiri daripada pelbagai kaum.", "isCorrect": true, "reaction": "Betul. Mereka inspirasi sukan masa kini."}, {"text": "Aku fikir atlet terdahulu tidak perlu dikenang, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pengulas menggeleng. Jasa mereka menjadi inspirasi."}, {"text": "Sebenarnya, hanya atlet semasa yang penting, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Atlet terdahulu meletakkan asas kejayaan masa kini."}], "clue": "Hargai jasa atlet terdahulu."}]}'),
(909, 'e9_n2_s1', 'Cari Bukti Kebanggaan Podium', 'Cari empat bukti kebanggaan negara di podium sukan.', '2', 'Memahami bahawa kejayaan atlet dapat dilihat melalui pingat emas, bendera, trofi dan sorakan rakyat.', '{"bgImage": "../assets/gameAsset/background/semua_podium_sukan.png", "hotspots": [{"name": "Pingat emas: lambang kebanggaan atlet negara", "top": "25.9%", "left": "27.9%"}, {"name": "Bendera Malaysia: kebanggaan negara", "top": "23%", "left": "50.8%"}, {"name": "Trofi diangkat: kejayaan atlet kebanggaan negara", "top": "37.6%", "left": "48.1%"}, {"name": "Penonton bersorak: rakyat bangga dengan atlet negara", "top": "88%", "left": "15%"}], "aftermath": "Bukti tidak ditemui dan murid menyangka atlet bertanding hanya untuk diri sendiri.", "turns": [{"after": 5, "options": [{"text": "Kita harus bangga apabila bendera negara berkibar dalam temasya sukan dunia.", "isCorrect": true, "reaction": "Betul, cikgu."}, {"text": "Atlet hanya bertanding untuk wang, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Cikgu menggeleng. Atlet mewakili negara."}, {"text": "Sebenarnya, kejayaan atlet tidak penting untuk rakyat, kerana itu lebih senang.", "isCorrect": false, "reaction": "Murid mengakui rakyat berasa bangga."}], "clue": "Atlet mengharumkan nama negara."}]}'),
(910, 'e9_n2_s2', 'Kad Lee Chong Wei', 'Baca kad dan tentukan pencapaian Lee Chong Wei.', '5', 'Memahami Lee Chong Wei: nombor satu dunia 2006, 2008, 2012 dan 2013; juara perseorangan lelaki Terbuka All England empat kali; Anugerah Pemain Lelaki Terbaik BWF lima kali.', '{"clueText": "Kad: Lee Chong Wei pernah memegang gelaran pemain badminton nombor satu dunia pada tahun 2006, 2008, 2012 dan 2013. Beliau juga juara Perseorangan Lelaki Terbuka All England sebanyak empat kali dan dinobatkan Anugerah Pemain Lelaki Terbaik oleh BWF sebanyak lima kali.", "options": [{"text": "Nombor satu dunia empat kali dan juara All England empat kali.", "isCorrect": true}, {"text": "Pemain skuasy wanita nombor satu dunia selama 108 bulan.", "isCorrect": false, "consequence": "Itu pencapaian Nicol Ann David."}, {"text": "Penyumbang pingat gangsa pertama negara di Olimpik London 2012.", "isCorrect": false, "consequence": "Itu pencapaian Pandelela Rinong."}, {"text": "Pelumba basikal pecut individu nombor satu dunia 2021.", "isCorrect": false, "consequence": "Itu pencapaian Mohd Azizulhasni Awang."}], "aftermath": "Kad tersalah baca dan murid menulis Lee Chong Wei pemain skuasy. Cikgu menggeleng.", "turns": [{"after": 5, "options": [{"text": "Kejayaan datang daripada kegigihan dan latihan.", "isCorrect": true, "reaction": "Betul. Murid mengambil raket."}, {"text": "Kejayaan datang tanpa usaha, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Cikgu menegur. Kejayaan datang dengan kegigihan."}, {"text": "Lee Chong Wei bermain bola sepak, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Beliau pemain badminton."}], "clue": "Kejayaan memerlukan kegigihan."}]}'),
(911, 'e9_n2_s3', 'Tiga Atlet Kebanggaan', 'Padankan atlet dengan pencapaiannya.', '4', 'Memahami: Nicol Ann David (skuasy nombor satu dunia 108 bulan; lapan kali juara Terbuka Dunia); Pandelela Rinong (terjun; gangsa pertama Olimpik London 2012; wanita pertama pembawa bendera); Azizulhasni (basikal trek; The Pocket Rocketman; gangsa Rio 2016, perak Tokyo 2020).', '{"pairs": [{"text": "Nicol Ann David", "pair": 1}, {"text": "Skuasy wanita nombor satu dunia selama 108 bulan", "pair": 1}, {"text": "Pandelela Rinong", "pair": 2}, {"text": "Gangsa pertama negara di Olimpik London 2012 dalam terjun", "pair": 2}, {"text": "Mohd Azizulhasni Awang", "pair": 3}, {"text": "The Pocket Rocketman; gangsa Rio 2016 dan perak Tokyo 2020", "pair": 3}, {"text": "Pembawa bendera wanita pertama", "pair": 4}, {"text": "Pandelela Rinong pada upacara pembukaan Sukan Olimpik", "pair": 4}], "aftermath": "Poster dipadankan dengan nama yang salah dan murid memberi tabik kepada atlet yang salah.", "turns": [{"after": 5, "options": [{"text": "Aku fikir atlet pelbagai kaum mengharumkan nama negara.", "isCorrect": true, "reaction": "Betul. Murid mengangguk."}, {"text": "Atlet hanya terdiri daripada satu kaum, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Cikgu membantah. Negara melahirkan atlet pelbagai kaum."}, {"text": "Atlet hanya menang di Malaysia, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Mereka juga menang di peringkat antarabangsa."}], "clue": "Atlet pelbagai kaum."}]}'),
(912, 'e9_n2_s4', 'Kad S. Kuhan', 'Baca kad dan tentukan rekod S. Kuhan dalam hoki.', '5', 'Memahami S. Kuhan: penjaring terbanyak Liga Hoki Malaysia 1997, 1999 dan 2003; ketua pasukan hoki 2000-2006; mewakili negara 341 kali.', '{"clueText": "Kad: S. Kuhan ialah penjaring terbanyak Liga Hoki Malaysia pada tahun 1997, 1999 dan 2003. Beliau merupakan ketua pasukan hoki Malaysia dari tahun 2000 hingga 2006 dan mewakili negara sebanyak 341 kali dalam pelbagai kejohanan utama hoki.", "options": [{"text": "Mewakili negara 341 kali dan ketua pasukan 2000 hingga 2006.", "isCorrect": true}, {"text": "Mewakili negara 167 kali dan menjaringkan 89 gol.", "isCorrect": false, "consequence": "Itu rekod Mokhtar Dahari dalam bola sepak."}, {"text": "Ketua pasukan badminton 2000 hingga 2006.", "isCorrect": false, "consequence": "S. Kuhan pemain hoki."}, {"text": "Pemenang tujuh emas Sukan SEA Bangkok 1985.", "isCorrect": false, "consequence": "Itu rekod Nurul Huda dalam renang."}], "aftermath": "Kad tersalah baca dan murid mengira S. Kuhan hanya sekali mewakili negara.", "turns": [{"after": 5, "options": [{"text": "Seorang ketua pasukan memimpin dengan teladan.", "isCorrect": true, "reaction": "Betul. Murid mengangguk."}, {"text": "Menurut aku, seorang ketua pasukan hanya perlu mengarah.", "isCorrect": false, "reaction": "Cikgu menegur. Ketua memimpin dengan teladan."}, {"text": "Seorang ketua tidak perlu berlatih.", "isCorrect": false, "reaction": "Ketua perlu menjadi contoh yang baik."}], "clue": "Ketua memimpin dengan teladan."}]}'),
(913, 'e9_n2_s5', 'Renang dan Bina Badan', 'Padankan atlet dengan pencapaiannya dalam renang dan bina badan.', '4', 'Memahami: Nurul Huda Abdullah (7 emas Bangkok 1985, 7 emas Jakarta 1987, 8 emas Kuala Lumpur 1989); Abdul Malek Mohamed Noor (enam kali Mr. Asia heavyweight; Olahragawan Negara 1986).', '{"pairs": [{"text": "Nurul Huda: Sukan SEA Bangkok 1985", "pair": 1}, {"text": "Tujuh pingat emas", "pair": 1}, {"text": "Nurul Huda: Sukan SEA Jakarta 1987", "pair": 2}, {"text": "Tujuh pingat emas lagi", "pair": 2}, {"text": "Nurul Huda: Sukan SEA Kuala Lumpur 1989", "pair": 3}, {"text": "Lapan pingat emas", "pair": 3}, {"text": "Abdul Malek: gelaran Mr. Asia", "pair": 4}, {"text": "Enam kali kategori heavyweight", "pair": 4}, {"text": "Abdul Malek: Olahragawan Negara", "pair": 5}, {"text": "Dianugerahkan pada tahun 1986", "pair": 5}], "aftermath": "Rekod bertukar dan murid mengira Nurul Huda hanya menang satu emas.", "turns": [{"after": 5, "options": [{"text": "Rekod itu hasil latihan dan semangat juang.", "isCorrect": true, "reaction": "Betul. Murid mencatat nota."}, {"text": "Rekod itu hasil nasib semata-mata.", "isCorrect": false, "reaction": "Cikgu menggeleng. Ia hasil latihan."}, {"text": "Rasanya, rekod itu tidak penting untuk dikenang.", "isCorrect": false, "reaction": "Rekod itu mengharumkan nama negara."}], "clue": "Rekod hasil latihan."}]}'),
(914, 'e9_n2_s6', 'Kad Team Secret MY', 'Baca kad dan tentukan pencapaian Team Secret MY.', '5', 'Memahami Team Secret MY: mewakili negara dalam e-sukan Kejohanan Final Global PUBG Mobile (PMGC) 2021 dan menduduki tempat ketujuh terbaik dunia.', '{"clueText": "Kad: Team Secret MY mewakili negara dalam e-sukan Kejohanan Final Global PUBG Mobile (PMGC) 2021. Pasukan ini menduduki tempat ketujuh terbaik dunia.", "options": [{"text": "Tempat ketujuh terbaik dunia dalam PMGC 2021.", "isCorrect": true}, {"text": "Juara pertama dunia dalam PMGC 2021.", "isCorrect": false, "consequence": "Kad menyebut tempat ketujuh."}, {"text": "Tempat ketujuh terbaik Asia dalam PMGC 2019.", "isCorrect": false, "consequence": "Kad menyebut PMGC 2021 dan peringkat dunia."}, {"text": "Tidak menyertai mana-mana kejohanan antarabangsa.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya."}], "aftermath": "Kad tersalah baca dan murid menyangka e-sukan negara tidak pernah bertanding di peringkat dunia.", "turns": [{"after": 5, "options": [{"text": "Pada pendapat aku, sukan baharu juga boleh mengharumkan nama negara.", "isCorrect": true, "reaction": "Betul. Murid berasa teruja."}, {"text": "Hanya sukan tradisional boleh mengharumkan nama negara.", "isCorrect": false, "reaction": "Cikgu menggeleng. E-sukan juga mewakili negara."}, {"text": "Menurut aku, e-sukan tidak boleh mewakili negara, kerana itu lebih senang.", "isCorrect": false, "reaction": "Team Secret MY mewakili Malaysia."}], "clue": "E-sukan juga mengharumkan nama negara."}]}'),
(915, 'e9_n2_s7', 'Atlet Paralimpik Kebanggaan', 'Padankan atlet paralimpik dengan pencapaiannya.', '4', 'Memahami atlet paralimpik: Bonnie Bunyau Gustin (angkat berat; emas Tokyo 2020), Muhammad Ziyad (lontar peluru F20; emas RIO 2016; 16.84 m), Mohamad Ridzuan (100 m T36; emas RIO 2016), Abdul Latif (lompat jauh T20; 7.60 m).', '{"pairs": [{"text": "Bonnie Bunyau Gustin", "pair": 1}, {"text": "Angkat berat; emas Paralimpik Tokyo 2020", "pair": 1}, {"text": "Muhammad Ziyad Zolkefli", "pair": 2}, {"text": "Lontar peluru F20; rekod dunia 16.84 meter", "pair": 2}, {"text": "Mohamad Ridzuan Mohamad Puzi", "pair": 3}, {"text": "100 meter T36 cerebral palsy; emas RIO 2016", "pair": 3}, {"text": "Abdul Latif Romly", "pair": 4}, {"text": "Lompat jauh T20; rekod dunia 7.60 meter", "pair": 4}, {"text": "Slogan atlet paralimpik negara", "pair": 5}, {"text": "Kami Luar Biasa", "pair": 5}], "aftermath": "Atlet dipadankan dengan acara yang salah dan murid menganggap atlet paralimpik kurang hebat.", "turns": [{"after": 7, "options": [{"text": "Kesungguhan atlet paralimpik patut menjadi teladan kepada semua.", "isCorrect": true, "reaction": "Betul. Perhimpunan bertepuk tangan."}, {"text": "Menurut aku, atlet paralimpik kurang layak dihargai, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Cikgu menegur. Mereka luar biasa."}, {"text": "Rasanya, atlet paralimpik hanya menyertai untuk suka-suka.", "isCorrect": false, "reaction": "Mereka memecah rekod dunia dan memenangi emas."}], "clue": "Atlet paralimpik: luar biasa."}]}'),
(916, 'e9_n2_s8', 'Kad Faedah Sukan Antarabangsa', 'Baca kad dan tentukan faedah menjadi tuan rumah sukan antarabangsa.', '5', 'Memahami faedah penganjuran sukan antarabangsa: negara dikenali di peringkat dunia, menarik pelancong luar negara, menyumbang kepada pembangunan ekonomi; negara dipercayai kerana infrastruktur sukan lengkap.', '{"clueText": "Kad: Negara kita diberikan kepercayaan sebagai tuan rumah sukan antarabangsa kerana memiliki infrastruktur sukan yang lengkap. Peranan ini menjadikan negara dikenali pada peringkat dunia, menarik kedatangan pelancong luar negara dan menyumbang kepada pembangunan ekonomi negara.", "options": [{"text": "Dikenali dunia, menarik pelancong dan menyumbang kepada ekonomi.", "isCorrect": true}, {"text": "Menjejaskan ekonomi dan menolak pelancong.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya."}, {"text": "Menghalang atlet tempatan bertanding.", "isCorrect": false, "consequence": "Kad tidak menyebut perkara itu."}, {"text": "Hanya menambah kos tanpa sebarang faedah.", "isCorrect": false, "consequence": "Kad menyatakan faedah kepada ekonomi."}], "aftermath": "Kad tersalah baca dan pengetua menyangka penganjuran sukan hanya membazir wang.", "turns": [{"after": 5, "options": [{"text": "Bagi aku, sukan antarabangsa membawa imej gemilang dan menambah pendapatan negara.", "isCorrect": true, "reaction": "Betul. Pengetua tersenyum."}, {"text": "Sukan antarabangsa hanya menyusahkan rakyat, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pengetua menggeleng. Ia membawa banyak faedah."}, {"text": "Sukan antarabangsa tidak berkaitan dengan ekonomi, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Pelancong luar menyumbang kepada ekonomi."}], "clue": "Sukan membawa imej gemilang."}]}'),
(917, 'e9_n3_s1', 'Enam Program Sukan Perpaduan', 'Padankan program sukan perpaduan dengan penerangannya.', '4', 'Memahami: RIMUP (2005), 1M1S (2011, setiap murid sekurang-kurangnya satu sukan), MSSM (tahunan), SUKMA (bergilir negeri), SUKIPT (peringkat IPT), Sukan Paralimpik (OKU).', '{"pairs": [{"text": "RIMUP, diperkenalkan tahun 2005", "pair": 1}, {"text": "Kerjasama aktiviti sukan antara sekolah memupuk perpaduan murid", "pair": 1}, {"text": "Dasar 1Murid 1Sukan, bermula 2011", "pair": 2}, {"text": "Setiap murid terlibat dalam sekurang-kurangnya satu bidang sukan", "pair": 2}, {"text": "Kejohanan MSSM", "pair": 3}, {"text": "Dianjurkan setiap tahun untuk atlet remaja", "pair": 3}, {"text": "Temasya Sukan Malaysia (SUKMA)", "pair": 4}, {"text": "Dianjurkan secara bergilir-gilir oleh setiap negeri", "pair": 4}, {"text": "SUKIPT", "pair": 5}, {"text": "Kejohanan atlet peringkat institusi pengajian tinggi", "pair": 5}, {"text": "Sukan Paralimpik", "pair": 6}, {"text": "Temasya sukan untuk Orang Kurang Upaya (OKU)", "pair": 6}], "aftermath": "Keratan bertukar dan buku skrap menyatakan SUKMA dianjurkan oleh sekolah. Cikgu menegur.", "turns": [{"after": 6, "options": [{"text": "Sukan memupuk perpaduan apabila pelbagai kaum bermain bersama.", "isCorrect": true, "reaction": "Betul. Buku skrap diteruskan."}, {"text": "Pada pendapat aku, sukan hanya untuk murid yang pandai bermain.", "isCorrect": false, "reaction": "Cikgu menegur. 1M1S melibatkan setiap murid."}, {"text": "Sukan memecahkan perpaduan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Sukan menyatukan pelbagai kaum."}], "clue": "Sukan memupuk perpaduan."}]}'),
(918, 'e9_n3_s2', 'Nota SUKMA', 'Baca nota dan tentukan temasya sukan terbesar dalam negara.', '5', 'Memahami SUKMA: sukan terbesar dalam negara, dianjurkan bergilir-gilir oleh setiap negeri; SUKMA pertama 1986; atlet pelbagai kaum mewakili negeri.', '{"clueText": "Nota: Temasya Sukan Malaysia (SUKMA) merupakan sukan terbesar dalam negara yang dianjurkan secara bergilir-gilir oleh setiap negeri. SUKMA pertama diadakan pada 1986. Pelibatan atlet pelbagai kaum yang mewakili setiap negeri berjaya membentuk masyarakat yang harmoni.", "options": [{"text": "SUKMA, dianjurkan bergilir-gilir oleh setiap negeri.", "isCorrect": true}, {"text": "MSSM, dianjurkan setiap tahun oleh sekolah sahaja.", "isCorrect": false, "consequence": "MSSM bukan temasya terbesar. Nota menyebut SUKMA."}, {"text": "SUKIPT, dianjurkan oleh institusi swasta sahaja.", "isCorrect": false, "consequence": "SUKIPT untuk atlet IPT."}, {"text": "RIMUP, dianjurkan setiap lima tahun.", "isCorrect": false, "consequence": "RIMUP ialah rancangan, bukan temasya terbesar."}], "aftermath": "Nota tersalah baca dan buku skrap mencatat MSSM sebagai temasya terbesar.", "turns": [{"after": 5, "options": [{"text": "Atlet pelbagai kaum yang mewakili negeri membentuk masyarakat harmoni.", "isCorrect": true, "reaction": "Betul. Murid mencatat nota."}, {"text": "Atlet hanya mewakili satu kaum di setiap negeri, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Nota menyatakan atlet pelbagai kaum."}, {"text": "SUKMA tidak berkaitan dengan perpaduan, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "SUKMA membentuk masyarakat yang harmoni."}], "clue": "SUKMA membentuk masyarakat harmoni."}]}'),
(919, 'e9_n3_s3', 'Peristiwa Sukan SEA', 'Susun peristiwa penting Sukan SEA mengikut urutan.', '1', 'Menyusun kronologi: Sukan SEAP mula dipertandingkan 1959; Malaysia tuan rumah pertama 1965; dikenali Sukan SEA pada 1977; Malaysia tuan rumah 2017.', '{"timelineItems": [{"id": 1, "year": "1959", "text": "Sukan SEAP (Southeast Asian Peninsular Games) mula dipertandingkan", "why": "Nama awal sebelum Sukan SEA."}, {"id": 2, "year": "1965", "text": "Malaysia menjadi tuan rumah kejohanan Sukan SEAP", "why": "Penganjuran 1965 hingga 1971 dikenali sebagai Sukan SEAP."}, {"id": 3, "year": "1977", "text": "Sukan SEAP dikenali sebagai Sukan SEA", "why": "Southeast Asian Games."}, {"id": 4, "year": "2017", "text": "Malaysia menjadi tuan rumah Sukan SEA di Kuala Lumpur", "why": "Tuan rumah yang terkini dalam sejarah unit ini."}], "aftermath": "Urutan tersilap dan buku skrap menyatakan Sukan SEA bermula pada 2017.", "turns": [{"after": 5, "options": [{"text": "Penganjuran Sukan SEA merapatkan hubungan antara negara serantau.", "isCorrect": true, "reaction": "Betul. Buku skrap lengkap."}, {"text": "Sukan SEA hanya dianjurkan oleh Malaysia, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Cikgu membetulkan. Negara serantau bergilir menjadi tuan rumah."}, {"text": "Sukan SEA tidak merapatkan hubungan negara, kerana itu lebih senang.", "isCorrect": false, "reaction": "Penganjurannya merapatkan hubungan serantau."}], "clue": "Sukan SEA merapatkan hubungan serantau."}]}'),
(920, 'e9_n3_s4', 'Piala Thomas dan Hoki Piala Dunia', 'Padankan kejohanan dengan tempat atau tahun penganjuran.', '4', 'Memahami: Piala Thomas enam kali (1970, 1984, 1988, 1992 di Stadium Negara; 2000, 2010 di Stadium Putra Bukit Jalil); Hoki Piala Dunia dua edisi (1975 Stadium Merdeka, 12 negara; 2002 Bukit Jalil, 16 negara).', '{"pairs": [{"text": "Piala Thomas 1970, 1984, 1988 dan 1992", "pair": 1}, {"text": "Stadium Negara, Kuala Lumpur", "pair": 1}, {"text": "Piala Thomas 2000 dan 2010", "pair": 2}, {"text": "Stadium Putra, Bukit Jalil", "pair": 2}, {"text": "Hoki Piala Dunia 1975", "pair": 3}, {"text": "Stadium Merdeka dengan 12 buah negara", "pair": 3}, {"text": "Hoki Piala Dunia 2002", "pair": 4}, {"text": "Stadium Hoki Nasional Bukit Jalil dengan 16 buah negara", "pair": 4}], "aftermath": "Padanan tersilap dan buku skrap menyatakan Hoki Piala Dunia 2002 dianjurkan di Stadium Merdeka.", "turns": [{"after": 6, "options": [{"text": "Pada pendapat aku, penganjuran kejohanan membawa imej gemilang kepada negara.", "isCorrect": true, "reaction": "Betul. Murid melengkapkan halaman."}, {"text": "Pada pendapat aku, penganjuran kejohanan tiada manfaat kepada negara.", "isCorrect": false, "reaction": "Cikgu menggeleng. Ia mendorong pembangunan sukan."}, {"text": "Pada pendapat aku, kejohanan hanya dianjurkan sekali sahaja, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Piala Thomas enam kali dan Hoki Piala Dunia dua kali."}], "clue": "Penganjuran membawa imej gemilang."}]}'),
(921, 'e9_n3_s5', 'Acara Antarabangsa di Malaysia', 'Padankan acara sukan antarabangsa dengan butirannya.', '4', 'Memahami: sukan permotoran (MotoGP, SBK) sejak 1991; Le Tour de Langkawi sejak 1996; Komanwel 1998; Formula One sejak 2000; Piala Monsun sejak 2005 (Pulau Duyong); Formula E 2014 di Putrajaya.', '{"pairs": [{"text": "MotoGP dan SBK", "pair": 1}, {"text": "Sukan permotoran antarabangsa bermula tahun 1991", "pair": 1}, {"text": "Le Tour de Langkawi", "pair": 2}, {"text": "Lumba basikal antarabangsa tahunan bermula tahun 1996", "pair": 2}, {"text": "Sukan Komanwel 1998", "pair": 3}, {"text": "Negara Asia pertama menjadi tuan rumah", "pair": 3}, {"text": "Formula One", "pair": 4}, {"text": "Dianjurkan di Sepang International Circuit sejak tahun 2000", "pair": 4}, {"text": "Formula E", "pair": 5}, {"text": "Diadakan di Putrajaya pada tahun 2014", "pair": 5}, {"text": "Piala Monsun", "pair": 6}, {"text": "Sukan perahu layar di Pulau Duyong, Terengganu sejak 2005", "pair": 6}], "aftermath": "Acara bertukar tempat dan buku skrap mencatat Formula E di Sepang pada tahun 2000.", "turns": [{"after": 6, "options": [{"text": "Pada pendapat aku, acara itu menarik pelancong dan menjana pendapatan negara.", "isCorrect": true, "reaction": "Betul. Murid mencatat."}, {"text": "Acara itu tidak berkaitan dengan pelancongan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Le Tour de Langkawi mempromosikan destinasi pelancongan."}, {"text": "Acara itu hanya untuk penduduk setempat, jadi kita tidak perlu ambil kisah.", "isCorrect": false, "reaction": "Peminat dari seluruh dunia hadir."}], "clue": "Acara menarik pelancong."}]}'),
(922, 'e9_n3_s6', 'Nota Sukan Komanwel 1998', 'Baca nota dan tentukan maklumat Sukan Komanwel 1998.', '5', 'Memahami Komanwel 1998: Malaysia negara Asia pertama menjadi tuan rumah; Stadium Nasional Bukit Jalil; maskot Orang Utan dan logo bunga raya; memupuk setia kawan sesama negara Komanwel.', '{"clueText": "Nota: Malaysia merupakan negara Asia pertama menjadi tuan rumah Sukan Komanwel, iaitu pada tahun 1998. Stadium Nasional Bukit Jalil menjadi stadium utama kejohanan. Imej Orang Utan dipilih sebagai maskot dan bunga raya menjadi logo kejohanan.", "options": [{"text": "Orang Utan maskot dan bunga raya logo; tuan rumah Asia pertama.", "isCorrect": true}, {"text": "Singa maskot dan melur logo.", "isCorrect": false, "consequence": "Nota menyebut Orang Utan dan bunga raya."}, {"text": "Harimau maskot dan kemboja logo.", "isCorrect": false, "consequence": "Nota menyebut Orang Utan dan bunga raya."}, {"text": "Gajah maskot dan teratai logo.", "isCorrect": false, "consequence": "Nota menyebut Orang Utan dan bunga raya."}], "aftermath": "Nota tersalah baca dan murid menggambar maskot yang salah. Kelas ketawa.", "turns": [{"after": 5, "options": [{"text": "Sukan Komanwel memupuk setia kawan sesama negara Komanwel.", "isCorrect": true, "reaction": "Betul. Murid mengangguk."}, {"text": "Sukan Komanwel hanya dianjurkan di Eropah, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Malaysia ialah negara Asia pertama tuan rumah."}, {"text": "Sukan Komanwel tiada kaitan dengan Malaysia, kerana itu lebih senang.", "isCorrect": false, "reaction": "Malaysia menjadi tuan rumah pada 1998."}], "clue": "Komanwel memupuk setia kawan."}]}'),
(923, 'e9_n3_s7', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan peranannya.', '4', 'Memahami cinta akan negara: diri (saling menghormati antara kaum melalui sukan), masyarakat (perpaduan dan keharmonian menjamin kesejahteraan), negara (keamanan dan kemakmuran dinikmati bersama).', '{"pairs": [{"text": "Diri", "pair": 1}, {"text": "Mengamalkan sikap saling menghormati antara kaum melalui sukan", "pair": 1}, {"text": "Masyarakat", "pair": 2}, {"text": "Perpaduan dan keharmonian kaum menjamin kesejahteraan masyarakat", "pair": 2}, {"text": "Negara", "pair": 3}, {"text": "Keamanan dan kemakmuran dinikmati bersama apabila perpaduan dikekalkan", "pair": 3}], "aftermath": "Padanan tersilap dan buku skrap menyatakan perpaduan hanya urusan negara.", "turns": [{"after": 5, "options": [{"text": "Perpaduan kaum perlu dikekalkan supaya sukan terus mencipta kecemerlangan.", "isCorrect": true, "reaction": "Betul. Cikgu tersenyum."}, {"text": "Pada pendapat aku, perpaduan tidak berkaitan dengan sukan, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Sukan ialah alat perpaduan."}, {"text": "Perpaduan hanya perlu semasa pertandingan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Perpaduan perlu dikekalkan sepanjang masa."}], "clue": "Kekalkan perpaduan kaum."}]}'),
(924, 'e9_n3_s8', 'Tiga Pemimpin Sukan', 'Padankan pemimpin sukan dengan jawatan atau sumbangannya.', '4', 'Mengenal pasti tokoh: Sultan Azlan Shah (Bapa Hoki Malaysia; Presiden Persekutuan Hoki Malaysia 1985-2004; Piala Sultan Azlan Shah sejak 1992); Dato'' Peter Velappan (Setiausaha Agung AFC 1978-2007); Dato'' Sieh Kok Chi (atlet polo air; Setiausaha Agung MOM 1992-2015).', '{"pairs": [{"text": "Sultan Azlan Muhibbuddin Shah", "pair": 1}, {"text": "Bapa Hoki Malaysia; Presiden Persekutuan Hoki Malaysia 1985-2004", "pair": 1}, {"text": "Piala Sultan Azlan Shah", "pair": 2}, {"text": "Kejohanan hoki lapan pasukan terbaik dunia sejak tahun 1992", "pair": 2}, {"text": "Dato'' Peter Velappan", "pair": 3}, {"text": "Setiausaha Agung Asian Football Confederation 1978-2007", "pair": 3}, {"text": "Dato'' Sieh Kok Chi", "pair": 4}, {"text": "Atlet polo air; Setiausaha Agung Majlis Olimpik Malaysia 1992-2015", "pair": 4}], "aftermath": "Tokoh bertukar jawatan dan buku skrap mencatat Sultan Azlan Shah sebagai Setiausaha AFC. Cikgu menegur.", "turns": [{"after": 6, "options": [{"text": "Kepimpinan sukan dan kerjasama atlet mengharumkan nama Malaysia.", "isCorrect": true, "reaction": "Betul. Buku skrap siap."}, {"text": "Hanya atlet yang mengharumkan nama negara, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Pemimpin sukan juga mengharumkan nama Malaysia."}, {"text": "Pemimpin sukan tidak perlu dihargai, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Cikgu menegur. Jasa mereka besar."}], "clue": "Pemimpin sukan juga berjasa."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e9_n1_s1', 'hint', 'Punch Gunalan, Misbun Sidek dan Lee Chong Wei ialah atlet BAM.', NULL, NULL),
(901, NULL, 'hint', 'BAM ditubuhkan 1960. Kejohanan Badminton Kebangsaan. Piala Thomas lima kali dan pingat Olimpik.', 'Aku membetulkan skrip siaran badminton. Persatuan Badminton Malaysia ditubuhkan pada tahun 1960, menganjurkan Kejohanan Badminton Kebangsaan, melahirkan Punch Gunalan, Misbun Sidek dan Lee Chong Wei, dan atletnya juara Piala Thomas lima kali serta memenangi pingat Olimpik.', 'Tepat! Pengulas Sukan menyelak skripnya dan siaran bermula dengan lancar.'),
(NULL, 'e9_n1_s2', 'hint', 'Nota menyebut All England Terbuka bagi acara beregu dan individu lelaki.', NULL, NULL),
(902, NULL, 'hint', 'Lima kali Piala Thomas serta pingat perak dan gangsa Olimpik.', 'Nota di bangku penonton menyebut atlet badminton negara juara Piala Thomas lima kali, memenangi pingat perak dan gangsa Olimpik serta menjuarai Kejohanan Terbuka All England bagi acara beregu dan individu lelaki.', 'Betul! Peminat di stadium bertepuk tangan apabila fakta itu dibacakan.'),
(NULL, 'e9_n1_s3', 'hint', 'Soh Chin Ann, James Wong dan Safawi Rasid ialah pemain berbakat.', NULL, NULL),
(903, NULL, 'hint', 'FAM 1963. Liga Bola Sepak Malaysia. Olimpik 1972 dan 1980. Juara Piala Suzuki 2010.', 'Aku menyusun fakta bola sepak. FAM ditubuhkan pada tahun 1963, menganjurkan Liga Bola Sepak Malaysia, melahirkan Soh Chin Ann, James Wong dan Safawi Rasid, layak ke Olimpik Munich 1972 dan Moscow 1980, dan menjuarai Piala Suzuki AFF pada tahun 2010.', 'Hebat! Peminat bersorak apabila fakta bola sepak tersusun semula.'),
(NULL, 'e9_n1_s4', 'hint', 'Anugerah lain milik atlet lain.', NULL, NULL),
(904, NULL, 'hint', 'Mohd Faiz Subri memenangi anugerah PUSKAS FIFA 2016.', 'Mohd Faiz Subri ketika menjadi pemain pasukan Pulau Pinang memenangi anugerah antarabangsa PUSKAS FIFA 2016. Anugerah Pemain Lelaki Terbaik BWF milik Lee Chong Wei, Atlet Terunggul Sukan Dunia milik Nicol Ann David dan Olahragawan Negara 1986 milik Abdul Malek.', 'Tepat! Pengulas Sukan membetulkan skrip dan meminta maaf kepada peminat.'),
(NULL, 'e9_n1_s5', 'hint', 'Emas 100 meter Sukan Asia pada 1966 dan 1982.', NULL, NULL),
(905, NULL, 'hint', 'Empat bukti. Pelari pecut, blok permulaan, pegawai berjam randik dan pelari kedua.', 'Aku mencari empat bukti dalam rakaman olahraga. Pelari pecut yang memenangi emas 100 meter Sukan Asia pada 1966 dan 1982, blok permulaan acara 100 meter, pegawai berjam randik yang menunjukkan olahraga diurus oleh KOM, dan pelari kedua atlet Malaysia di Sukan SEA.', 'Cekap! Rakaman lama itu menjadi bukti sejarah olahraga negara.'),
(NULL, 'e9_n1_s6', 'hint', 'Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek ialah atlet olahraga.', NULL, NULL),
(906, NULL, 'hint', 'KOAM 1952, kini KOM. Sukan SEA 2017 dengan lapan emas.', 'KOAM ditubuhkan pada tahun 1952 dan kini dikenali sebagai KOM. KOM menganjurkan Kejohanan Olahraga Kebangsaan, melahirkan Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek, dan atlet olahraga membantu negara juara Sukan SEA 2017 dengan lapan pingat emas.', 'Betul! Persatuan lain tidak lagi tertukar dengan KOM dalam skrip siaran.'),
(NULL, 'e9_n1_s7', 'hint', 'Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi.', NULL, NULL),
(907, NULL, 'hint', 'MHC 1953. Lapan kali Piala Dunia. Tempat keempat 1975. Naib juara Komanwel 1998.', 'Aku menyusun fakta hoki. MHC ditubuhkan pada tahun 1953 dan menganjurkan Liga Hoki Kebangsaan, melahirkan Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi. Negara layak ke Hoki Piala Dunia sebanyak lapan kali, tempat keempat pada 1975 dan naib juara Sukan Komanwel 1998.', 'Tepat! Kapten pasukan hoki mengangguk kerana semua angka berada di tempatnya.'),
(NULL, 'e9_n1_s8', 'hint', '167 penampilan antarabangsa dan 89 gol milik Mokhtar Dahari.', NULL, NULL),
(908, NULL, 'hint', 'Jegathesan Manusia Terpantas Asia. Rajamani Olimpik 1964. Tan Aik Huang All England 1966. Mokhtar Supermokh.', 'Siaran ditutup dengan empat legenda. Dr. M. Jegathesan ialah Manusia Terpantas Asia dengan tiga emas Sukan Asia Bangkok 1966, M. Rajamani atlet olahraga wanita di Olimpik 1964, Tan Aik Huang juara perseorangan lelaki All England 1966, dan Mokhtar Dahari digelar Supermokh dengan 167 penampilan dan 89 gol.', 'Tahniah! Pengulas Sukan menyerahkan mikrofon siarannya kepadamu sebagai kenang-kenangan.'),
(NULL, 'e9_n2_s1', 'hint', 'Semuanya lambang kebanggaan terhadap atlet negara.', NULL, NULL),
(909, NULL, 'hint', 'Empat bukti. Pingat emas, bendera Malaysia, trofi diangkat dan penonton bersorak.', 'Pada latihan pagi aku mencari empat tanda kebanggaan di podium. Pingat emas lambang kebanggaan atlet, bendera Malaysia lambang kebanggaan negara, trofi yang diangkat lambang kejayaan atlet dan penonton bersorak yang bangga dengan atlet negara.', 'Cekap! Jurulatih tersenyum kerana keempat-empat tanda kebanggaan itu dijumpai.'),
(NULL, 'e9_n2_s2', 'hint', 'Lima kali Anugerah Pemain Lelaki Terbaik BWF.', NULL, NULL),
(910, NULL, 'hint', 'Empat kali nombor satu dunia dan empat kali juara All England.', 'Lee Chong Wei pernah menjadi pemain badminton nombor satu dunia pada tahun 2006, 2008, 2012 dan 2013, juara Perseorangan Lelaki Terbuka All England sebanyak empat kali, dan dinobatkan Anugerah Pemain Lelaki Terbaik BWF sebanyak lima kali.', 'Betul! Murid-murid mengambil raket dan mula berlatih dengan semangat baharu.'),
(NULL, 'e9_n2_s3', 'hint', 'Pandelela ialah pembawa bendera wanita pertama pada upacara pembukaan Olimpik.', NULL, NULL),
(911, NULL, 'hint', 'Nicol 108 bulan. Pandelela gangsa London 2012. Azizulhasni The Pocket Rocketman.', 'Aku bertemu tiga atlet kebanggaan. Nicol Ann David skuasy wanita nombor satu dunia selama 108 bulan, Pandelela Rinong gangsa pertama negara di Olimpik London 2012 dalam terjun dan pembawa bendera wanita pertama, dan Mohd Azizulhasni Awang The Pocket Rocketman dengan gangsa Rio 2016 dan perak Tokyo 2020.', 'Hebat! Murid-murid melihat atlet pelbagai kaum berdiri sebagai satu pasukan.'),
(NULL, 'e9_n2_s4', 'hint', 'Penjaring terbanyak liga pada 1997, 1999 dan 2003.', NULL, NULL),
(912, NULL, 'hint', '341 kali mewakili negara dan ketua pasukan 2000 hingga 2006.', 'S. Kuhan ialah penjaring terbanyak Liga Hoki Malaysia pada tahun 1997, 1999 dan 2003, ketua pasukan hoki Malaysia dari tahun 2000 hingga 2006, dan mewakili negara sebanyak 341 kali dalam pelbagai kejohanan utama.', 'Betul! Murid-murid mengangguk apabila rekod ketua pasukan itu dibacakan.'),
(NULL, 'e9_n2_s5', 'hint', 'Nurul Huda renang, Abdul Malek bina badan.', NULL, NULL),
(913, NULL, 'hint', 'Nurul Huda 1985 tujuh emas, 1987 tujuh emas, 1989 lapan emas. Abdul Malek Mr. Asia dan Olahragawan Negara 1986.', 'Nurul Huda Abdullah memenangi tujuh emas di Sukan SEA Bangkok 1985, tujuh emas lagi di Jakarta 1987 dan lapan emas di Kuala Lumpur 1989. Abdul Malek digelar Mr. Asia enam kali dalam kategori heavyweight dan dianugerahkan Olahragawan Negara pada tahun 1986.', 'Tepat! Murid-murid mencatat rekod renang dan bina badan itu dalam buku latihan.'),
(NULL, 'e9_n2_s6', 'hint', 'PMGC ialah Kejohanan Final Global PUBG Mobile.', NULL, NULL),
(914, NULL, 'hint', 'Team Secret MY tempat ketujuh terbaik dunia dalam PMGC 2021.', 'Team Secret MY mewakili negara dalam e-sukan Kejohanan Final Global PUBG Mobile atau PMGC 2021 dan menduduki tempat ketujuh terbaik dunia.', 'Betul! Murid-murid teruja kerana e-sukan pun boleh mengharumkan nama negara.'),
(NULL, 'e9_n2_s7', 'hint', 'Slogan atlet paralimpik negara ialah Kami Luar Biasa.', NULL, NULL),
(915, NULL, 'hint', 'Bonnie angkat berat, Ziyad lontar peluru, Ridzuan 100 meter T36, Latif lompat jauh T20.', 'Atlet paralimpik negara luar biasa. Bonnie Bunyau Gustin emas angkat berat Tokyo 2020, Muhammad Ziyad Zolkefli rekod dunia lontar peluru F20 16.84 meter, Mohamad Ridzuan emas 100 meter T36 Rio 2016, Abdul Latif Romly rekod dunia lompat jauh T20 7.60 meter. Slogan mereka Kami Luar Biasa.', 'Tepat! Perhimpunan bertepuk tangan untuk semangat atlet paralimpik negara.'),
(NULL, 'e9_n2_s8', 'hint', 'Negara dipercayai kerana infrastruktur sukan yang lengkap.', NULL, NULL),
(916, NULL, 'hint', 'Dikenali dunia, menarik pelancong dan menyumbang kepada ekonomi.', 'Negara dipercayai menjadi tuan rumah sukan antarabangsa kerana memiliki infrastruktur sukan yang lengkap. Peranan ini menjadikan negara dikenali dunia, menarik pelancong luar negara dan menyumbang kepada pembangunan ekonomi negara.', 'Betul! Pengetua tersenyum apabila faedah sukan antarabangsa dihuraikan.'),
(NULL, 'e9_n3_s1', 'hint', 'Paralimpik ialah temasya sukan untuk OKU.', NULL, NULL),
(917, NULL, 'hint', 'RIMUP 2005. 1Murid 1Sukan 2011. MSSM setiap tahun. SUKMA bergilir. SUKIPT dan Paralimpik.', 'Aku menyusun enam program sukan perpaduan. RIMUP pada 2005, Dasar 1Murid 1Sukan pada 2011, Kejohanan MSSM setiap tahun, SUKMA yang dianjurkan bergilir-gilir oleh negeri, SUKIPT untuk institusi pengajian tinggi dan Sukan Paralimpik untuk OKU.', 'Betul! Buku skrap kini kemas dan enam program itu berada di tempat yang betul.'),
(NULL, 'e9_n3_s2', 'hint', 'SUKMA yang pertama diadakan pada tahun 1986.', NULL, NULL),
(918, NULL, 'hint', 'SUKMA, dianjurkan bergilir-gilir oleh setiap negeri.', 'Temasya Sukan Malaysia atau SUKMA ialah sukan terbesar dalam negara yang dianjurkan secara bergilir-gilir oleh setiap negeri. SUKMA pertama diadakan pada 1986 dan atlet pelbagai kaum yang mewakili negeri membentuk masyarakat yang harmoni.', 'Tepat! Murid Peminat Sukan menampal nota SUKMA di halaman buku skrapnya.'),
(NULL, 'e9_n3_s3', 'hint', 'Penganjuran 1965 hingga 1971 dikenali sebagai Sukan SEAP.', NULL, NULL),
(919, NULL, 'hint', '1959 SEAP bermula. 1965 tuan rumah. 1977 menjadi Sukan SEA. 2017 tuan rumah di Kuala Lumpur.', 'Aku menyusun garis masa Sukan SEA. Sukan SEAP mula dipertandingkan pada 1959, Malaysia menjadi tuan rumah SEAP pada 1965, SEAP dikenali sebagai Sukan SEA pada 1977, dan Malaysia menjadi tuan rumah Sukan SEA di Kuala Lumpur pada 2017.', 'Betul! Keratan akhbar tersusun semula dan buku skrap hampir lengkap.'),
(NULL, 'e9_n3_s4', 'hint', 'Negara menganjurkan Piala Thomas sebanyak enam kali.', NULL, NULL),
(920, NULL, 'hint', 'Piala Thomas di Stadium Negara dan Stadium Putra. Hoki 1975 di Merdeka dan 2002 di Bukit Jalil.', 'Aku memadankan kejohanan dan stadium. Piala Thomas 1970, 1984, 1988 dan 1992 di Stadium Negara, 2000 dan 2010 di Stadium Putra Bukit Jalil, jadi enam kali. Hoki Piala Dunia 1975 di Stadium Merdeka dengan 12 negara dan 2002 di Stadium Hoki Nasional Bukit Jalil dengan 16 negara.', 'Hebat! Murid Peminat Sukan melengkapkan halaman Piala Thomas dan Hoki Piala Dunia.'),
(NULL, 'e9_n3_s5', 'hint', 'Piala Monsun diadakan di Pulau Duyong, Terengganu.', NULL, NULL),
(921, NULL, 'hint', 'MotoGP 1991. Le Tour 1996. Komanwel 1998. Formula One 2000. Formula E 2014. Piala Monsun 2005.', 'Aku memadankan acara antarabangsa di Malaysia. MotoGP dan SBK bermula 1991, Le Tour de Langkawi 1996, Sukan Komanwel 1998 dengan negara Asia pertama sebagai tuan rumah, Formula One di Sepang sejak 2000, Formula E di Putrajaya 2014 dan Piala Monsun di Pulau Duyong sejak 2005.', 'Betul! Tiket-tiket itu diasingkan mengikut acara dan tarikhnya.'),
(NULL, 'e9_n3_s6', 'hint', 'Stadium Nasional Bukit Jalil ialah stadium utama.', NULL, NULL),
(922, NULL, 'hint', 'Orang Utan maskot dan bunga raya logo. Tuan rumah Asia pertama.', 'Malaysia ialah negara Asia pertama menjadi tuan rumah Sukan Komanwel pada tahun 1998. Stadium Nasional Bukit Jalil menjadi stadium utama, imej Orang Utan dipilih sebagai maskot dan bunga raya menjadi logo kejohanan.', 'Tepat! Maskot dan logo itu ditampal kemas di halaman hadapan buku skrap.'),
(NULL, 'e9_n3_s7', 'hint', 'Tiga peringkat. Diri, masyarakat dan negara.', NULL, NULL),
(923, NULL, 'hint', 'Diri dengan sikap hormat. Masyarakat dengan kesejahteraan. Negara dengan keamanan dan kemakmuran.', 'Aku belajar tiga peringkat perpaduan melalui sukan. Diri mengamalkan sikap saling menghormati antara kaum, masyarakat menikmati kesejahteraan melalui perpaduan dan keharmonian, dan negara menikmati keamanan dan kemakmuran bersama apabila perpaduan dikekalkan.', 'Betul! Cikgu tersenyum kerana tiga peringkat itu dijelaskan dengan baik.'),
(NULL, 'e9_n3_s8', 'hint', 'Piala Sultan Azlan Shah ialah kejohanan lapan pasukan terbaik dunia.', NULL, NULL),
(924, NULL, 'hint', 'Sultan Azlan Bapa Hoki dan Piala 1992. Velappan AFC 1978-2007. Sieh Majlis Olimpik 1992-2015.', 'Buku skrap ditutup dengan tiga pemimpin sukan. Sultan Azlan Muhibbuddin Shah ialah Bapa Hoki Malaysia dan Presiden Persekutuan Hoki Malaysia 1985 hingga 2004, Dato'' Peter Velappan Setiausaha Agung AFC 1978 hingga 2007, dan Dato'' Sieh Kok Chi atlet polo air dan Setiausaha Agung Majlis Olimpik Malaysia 1992 hingga 2015.', 'Tahniah! Buku skrap lengkap dan Murid Peminat Sukan menghadiahkan satu halaman istimewa kepadamu.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(161, 901, NULL, 'Tugasku mengulas pencapaian sukan negara dengan tepat. Jika nama atau tahun salah, peminat akan menegur siaran kita, {nama}.', 1),
(161, 901, NULL, 'Aku belajar bahawa atlet pelbagai kaum yang gigih mengharumkan nama negara dan wajar dihargai.', 2),
(161, 901, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengulas sukan di stadium. Rakam kejayaan atlet dengan tepat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(161, 901, 'e9_n1_s1', 'Dua minit lagi siaran bermula dan skrip aku basah kena teh tarik. Tahun penubuhan Persatuan Badminton Malaysia pun aku sudah tidak pasti.', 1),
(164, 901, 'e9_n1_s1', 'Aku Lee Chong Wei. Persatuan Badminton Malaysia, atau BAM, ditubuhkan pada tahun 1960. Persatuan inilah yang menganjurkan Kejohanan Badminton Kebangsaan.', 2),
(164, 901, 'e9_n1_s1', 'Daripada kejohanan itu lahir atlet kebanggaan seperti Punch Gunalan, Misbun Sidek dan aku sendiri. Pencapaian antarabangsa kami pula juara Piala Thomas lima kali dan pingat Olimpik.', 3),
(NULL, 901, 'e9_n1_s1', 'Aku akan padankan tahun, kejohanan, atlet dan pencapaian itu.', 4),
(161, 901, 'e9_n1_s1', 'Betulkan skrip aku cepat. Selepas semua itu, apakah peranan sebuah persatuan sukan?', 5),
(163, 901, 'e9_n1_s2', 'Pengulas, kad catatan ini tertinggal di bangku penonton. Tulisannya hampir luntur.', 1),
(161, 901, 'e9_n1_s2', 'Bacalah dengan kuat. Peminat di rumah mahu tahu apa pencapaian badminton kita di peringkat antarabangsa.', 2),
(163, 901, 'e9_n1_s2', 'Atlet negara juara Piala Thomas sebanyak lima kali dan memenangi pingat perak serta gangsa Olimpik. Mereka juga menjuarai All England Terbuka bagi acara beregu dan individu lelaki.', 3),
(NULL, 901, 'e9_n1_s2', 'Aku akan pilih pencapaian yang sama dengan nota itu.', 4),
(161, 901, 'e9_n1_s2', 'Pilih dengan tepat kerana pendengar menanti. Dan bagaimana perasaan kita terhadap kejayaan ini?', 5),
(161, 901, 'e9_n1_s3', 'Sekarang bola sepak. Siapa boleh bantu aku susun fakta Persatuan Bola Sepak Malaysia?', 1),
(163, 901, 'e9_n1_s3', 'FAM ditubuhkan pada tahun 1963. Pertandingan yang dianjurkan FAM ialah Liga Bola Sepak Malaysia, tempat pemain berbakat seperti Soh Chin Ann, James Wong dan Safawi Rasid dilahirkan.', 2),
(163, 901, 'e9_n1_s3', 'Pasukan negara pernah layak ke Sukan Olimpik di Munich pada 1972 dan di Moscow pada 1980. Pada tahun 2010 pasukan kita juara Piala Suzuki AFF.', 3),
(NULL, 901, 'e9_n1_s3', 'Aku akan padankan tahun, liga, pemain, Olimpik dan Piala Suzuki.', 4),
(161, 901, 'e9_n1_s3', 'Jangan silap kerana ini siaran langsung. Apakah yang melahirkan pemain berbakat negara?', 5),
(163, 901, 'e9_n1_s4', 'Anugerah antarabangsa apa yang pernah dimenangi pemain bola sepak kita dari Pulau Pinang?', 1),
(161, 901, 'e9_n1_s4', 'Nota ringkas ini menyebut Mohd Faiz Subri ketika menjadi pemain pasukan Pulau Pinang memenangi anugerah antarabangsa PUSKAS FIFA 2016.', 2),
(163, 901, 'e9_n1_s4', 'Jangan keliru dengan anugerah lain. Anugerah Pemain Lelaki Terbaik BWF milik Lee Chong Wei, anugerah Atlet Terunggul Sukan Dunia milik Nicol Ann David dan anugerah Olahragawan Negara 1986 milik Abdul Malek.', 3),
(NULL, 901, 'e9_n1_s4', 'Aku akan pilih anugerah yang betul. PUSKAS FIFA 2016.', 4),
(161, 901, 'e9_n1_s4', 'Baik, kalau betul aku mohon maaf kerana tersilap tadi. Jadi apakah yang dibuktikan oleh pemain tempatan itu?', 5),
(161, 901, 'e9_n1_s5', 'Dalam rakaman lama ini ada empat bukti kegemilangan olahraga kita. Aku mahu pelajar mencarinya.', 1),
(179, 901, 'e9_n1_s5', 'Aku Dr. M. Jegathesan. Pelari pecut di tengah memenangi pingat emas 100 meter Sukan Asia pada tahun 1966 dan pada tahun 1982.', 2),
(179, 901, 'e9_n1_s5', 'Blok permulaan di bawah ialah acara 100 meter Sukan Asia. Pegawai berjam randik di kiri menunjukkan olahraga diurus oleh KOM, dan pelari kedua mewakili atlet Malaysia dalam Kejohanan Sukan SEA.', 3),
(NULL, 901, 'e9_n1_s5', 'Pelari pecut, blok permulaan, pegawai berjam randik dan pelari kedua. Aku akan cari keempat-empatnya.', 4),
(161, 901, 'e9_n1_s5', 'Cari betul-betul kerana rakaman ini bukti sejarah. Jadi siapakah di sebalik kejayaan olahraga itu?', 5),
(180, 901, 'e9_n1_s6', 'Aku M. Rajamani. Kesatuan Olahraga Amatur Malaysia atau KOAM ditubuhkan pada tahun 1952 dan kini dikenali sebagai Kesatuan Olahraga Malaysia atau KOM.', 1),
(161, 901, 'e9_n1_s6', 'KOM menganjurkan Kejohanan Olahraga Kebangsaan. Daripadanya lahir Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek.', 2),
(180, 901, 'e9_n1_s6', 'Dalam Sukan SEA 2017 atlet olahraga membantu negara muncul juara dengan menyumbang lapan pingat emas.', 3),
(NULL, 901, 'e9_n1_s6', 'Aku akan pilih maklumat yang betul tentang KOAM dan KOM.', 4),
(161, 901, 'e9_n1_s6', 'Jangan keliru dengan persatuan lain. Dan apakah yang disokong oleh persatuan sukan?', 5),
(161, 901, 'e9_n1_s7', 'Hoki pula. Nombor-nombor di skrip ini bergelut sesama sendiri.', 1),
(166, 901, 'e9_n1_s7', 'Aku S. Kuhan. Konfederasi Hoki Malaysia atau MHC ditubuhkan pada tahun 1953. Pertandingan yang dianjurkan ialah Liga Hoki Kebangsaan.', 2),
(166, 901, 'e9_n1_s7', 'Pemain hoki berbakat ialah Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi. Negara layak ke Hoki Piala Dunia sebanyak lapan kali dan mendapat tempat keempat pada tahun 1975.', 3),
(166, 901, 'e9_n1_s7', 'Pada tahun 1998 pasukan kita menjadi naib juara Sukan Komanwel.', 4),
(NULL, 901, 'e9_n1_s7', 'Aku akan padankan tahun, liga, pemain dan pencapaian itu.', 5),
(161, 901, 'e9_n1_s7', 'Jangan salah kerana kapten akan marah. Apakah erti kejayaan hoki itu kepada negara?', 6),
(161, 901, 'e9_n1_s8', 'Penutup siaran. Aku mahu menyebut empat legenda yang membuka jalan sebelum kita semua.', 1),
(179, 901, 'e9_n1_s8', 'Aku Dr. M. Jegathesan, digelar Manusia Terpantas Asia kerana memenangi tiga emas Sukan Asia di Bangkok pada tahun 1966.', 2),
(180, 901, 'e9_n1_s8', 'Aku M. Rajamani, atlet olahraga wanita yang mewakili negara di Olimpik 1964. Tan Aik Huang pula juara perseorangan lelaki All England pada tahun 1966.', 3),
(182, 901, 'e9_n1_s8', 'Aku Mokhtar Dahari, digelar Supermokh. Aku mencatat 167 penampilan antarabangsa dan menjaringkan 89 gol.', 4),
(NULL, 901, 'e9_n1_s8', 'Aku akan padankan legenda dengan pencapaian mereka.', 5),
(161, 901, 'e9_n1_s8', 'Padankan dengan betul sebelum siaran berakhir. Mengapa kita perlu menghargai jasa mereka?', 6),
(162, 902, NULL, 'Tugasku menunjuk teladan atlet kepada murid. Jika aku silap tentang pencapaian mereka, murid akan hilang kepercayaan, {nama}.', 1),
(162, 902, NULL, 'Aku belajar bahawa atlet pelbagai kaum dan atlet paralimpik mengharumkan nama negara dan wajar dihargai.', 2),
(162, 902, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, jurulatih sekolah di padang. Beri semangat kepada murid dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(162, 902, 'e9_n2_s1', 'Murid-murid, sebelum berlari mari kita lihat gambar podium ini. Ada empat tanda kebanggaan yang aku mahu kamu cari.', 1),
(163, 902, 'e9_n2_s1', 'Pingat emas ialah lambang kebanggaan atlet negara, cikgu. Bendera Malaysia itu pula lambang kebanggaan negara.', 2),
(163, 902, 'e9_n2_s1', 'Trofi yang diangkat menunjukkan kejayaan atlet kebanggaan negara, dan penonton yang bersorak menunjukkan rakyat bangga dengan atlet negara.', 3),
(NULL, 902, 'e9_n2_s1', 'Pingat emas, bendera Malaysia, trofi diangkat dan penonton bersorak. Aku akan cari keempat-empatnya.', 4),
(162, 902, 'e9_n2_s1', 'Cepat kerana kawan-kawan menunggu. Bagaimanakah perasaan kita apabila bendera negara berkibar di temasya dunia?', 5),
(162, 902, 'e9_n2_s2', 'Hari ini kita belajar daripada Lee Chong Wei. Ada kad rekod di tangan murid ini.', 1),
(164, 902, 'e9_n2_s2', 'Aku pernah menjadi pemain badminton nombor satu dunia pada tahun 2006, 2008, 2012 dan 2013.', 2),
(164, 902, 'e9_n2_s2', 'Aku juga juara Perseorangan Lelaki Terbuka All England sebanyak empat kali dan dinobatkan Anugerah Pemain Lelaki Terbaik BWF sebanyak lima kali.', 3),
(NULL, 902, 'e9_n2_s2', 'Aku akan pilih rekod yang betul. Nombor satu dunia empat kali dan juara All England empat kali.', 4),
(162, 902, 'e9_n2_s2', 'Baik, pilih dengan teliti. Dan apakah rahsia kejayaan seorang juara dunia?', 5),
(165, 902, 'e9_n2_s3', 'Aku Nicol Ann David. Aku skuasy wanita nombor satu dunia selama 108 bulan.', 1),
(167, 902, 'e9_n2_s3', 'Aku Pandelela Rinong. Aku menyumbang gangsa pertama negara di Olimpik London 2012 dalam terjun, dan aku pembawa bendera wanita pertama pada upacara pembukaan Sukan Olimpik.', 2),
(168, 902, 'e9_n2_s3', 'Aku Mohd Azizulhasni Awang, digelar The Pocket Rocketman. Aku memenangi gangsa Rio 2016 dan perak Tokyo 2020.', 3),
(NULL, 902, 'e9_n2_s3', 'Aku akan padankan atlet dengan pencapaian mereka.', 4),
(162, 902, 'e9_n2_s3', 'Padankan dengan betul. Apakah yang menyatukan ketiga-tiga atlet daripada kaum berbeza ini?', 5),
(166, 902, 'e9_n2_s4', 'Aku S. Kuhan, penjaring terbanyak Liga Hoki Malaysia pada tahun 1997, 1999 dan 2003.', 1),
(162, 902, 'e9_n2_s4', 'Ceritakan tentang pasukan kebangsaan pula, kerana murid-murid mahu tahu tugas seorang ketua.', 2),
(166, 902, 'e9_n2_s4', 'Aku ketua pasukan hoki Malaysia dari tahun 2000 hingga 2006 dan mewakili negara sebanyak 341 kali dalam pelbagai kejohanan utama.', 3),
(NULL, 902, 'e9_n2_s4', 'Aku akan pilih kad yang sepadan dengan rekod S. Kuhan.', 4),
(162, 902, 'e9_n2_s4', 'Teliti kerana nanti murid salah faham. Jadi apakah yang boleh kita contohi daripada seorang ketua pasukan?', 5),
(170, 902, 'e9_n2_s5', 'Aku Nurul Huda Abdullah. Di Sukan SEA Bangkok 1985 aku memenangi tujuh pingat emas, dan di Sukan SEA Jakarta 1987 aku memenangi tujuh pingat emas lagi.', 1),
(170, 902, 'e9_n2_s5', 'Di Sukan SEA Kuala Lumpur 1989 pula aku memenangi lapan pingat emas.', 2),
(171, 902, 'e9_n2_s5', 'Aku Abdul Malek Mohamed Noor. Aku digelar Mr. Asia enam kali dalam kategori heavyweight bina badan, dan dianugerahkan Olahragawan Negara pada tahun 1986.', 3),
(NULL, 902, 'e9_n2_s5', 'Aku akan padankan rekod setiap atlet dengan butirannya.', 4),
(162, 902, 'e9_n2_s5', 'Cekap, tetapi jangan campur tahun. Apakah yang memungkinkan rekod sebanyak itu?', 5),
(162, 902, 'e9_n2_s6', 'Sukan baharu pun boleh membanggakan negara. Murid-murid, ada sesiapa kenal e-sukan?', 1),
(169, 902, 'e9_n2_s6', 'Kami Team Secret MY. Kami mewakili negara dalam Kejohanan Final Global PUBG Mobile atau PMGC 2021.', 2),
(169, 902, 'e9_n2_s6', 'Kami menduduki tempat ketujuh terbaik dunia.', 3),
(NULL, 902, 'e9_n2_s6', 'Aku akan pilih kad yang betul. Tempat ketujuh terbaik dunia dalam PMGC 2021.', 4),
(162, 902, 'e9_n2_s6', 'Jawab dengan fakta, bukan agakan. Jadi bolehkah sukan baharu turut mengharumkan nama negara?', 5),
(172, 902, 'e9_n2_s7', 'Aku Bonnie Bunyau Gustin dalam angkat berat. Aku memenangi emas Paralimpik Tokyo 2020.', 1),
(173, 902, 'e9_n2_s7', 'Aku Muhammad Ziyad Zolkefli dalam lontar peluru F20. Rekod dunia aku ialah 16.84 meter.', 2),
(174, 902, 'e9_n2_s7', 'Aku Mohamad Ridzuan Mohamad Puzi dalam 100 meter T36 untuk cerebral palsy. Aku memenangi emas Rio 2016.', 3),
(175, 902, 'e9_n2_s7', 'Aku Abdul Latif Romly dalam lompat jauh T20. Rekod dunia aku ialah 7.60 meter.', 4),
(162, 902, 'e9_n2_s7', 'Slogan atlet paralimpik negara ialah Kami Luar Biasa.', 5),
(NULL, 902, 'e9_n2_s7', 'Aku akan padankan atlet dengan acara dan rekod mereka.', 6),
(162, 902, 'e9_n2_s7', 'Padankan dengan betul. Apakah yang boleh kita pelajari daripada kesungguhan mereka?', 7),
(162, 902, 'e9_n2_s8', 'Pengetua bertanya, mengapa negara kita dipercayai menjadi tuan rumah sukan antarabangsa?', 1),
(163, 902, 'e9_n2_s8', 'Kad ini menyebut negara kita memiliki infrastruktur sukan yang lengkap, cikgu.', 2),
(162, 902, 'e9_n2_s8', 'Peranan itu menjadikan negara dikenali pada peringkat dunia, menarik kedatangan pelancong luar negara dan menyumbang kepada pembangunan ekonomi negara.', 3),
(NULL, 902, 'e9_n2_s8', 'Aku akan pilih faedah yang sama dengan kad itu.', 4),
(162, 902, 'e9_n2_s8', 'Pilih dengan teliti. Jadi apakah yang negara peroleh apabila menjadi tuan rumah?', 5),
(163, 903, NULL, 'Tugasku mengisi buku skrap dengan keratan yang tepat. Jika aku tersilap, buku ini tidak boleh dijadikan rujukan, {nama}.', 1),
(163, 903, NULL, 'Aku belajar bahawa sukan memupuk perpaduan dan keharmonian kaum serta membawa pembangunan kepada negara.', 2),
(163, 903, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid peminat sukan dengan buku skrap. Semak setiap keratan dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(163, 903, 'e9_n3_s1', 'Buku skrap aku ada enam program sukan perpaduan tetapi keterangannya bercampur.', 1),
(162, 903, 'e9_n3_s1', 'RIMUP, Rancangan Integrasi Murid Untuk Perpaduan, diperkenalkan pada tahun 2005. Ia kerjasama aktiviti sukan antara sekolah untuk memupuk perpaduan murid.', 2),
(162, 903, 'e9_n3_s1', 'Dasar 1Murid 1Sukan bermula pada tahun 2011 supaya setiap murid terlibat dalam sekurang-kurangnya satu bidang sukan. Kejohanan MSSM dianjurkan setiap tahun untuk atlet remaja.', 3),
(162, 903, 'e9_n3_s1', 'Temasya Sukan Malaysia atau SUKMA dianjurkan secara bergilir-gilir oleh setiap negeri. SUKIPT untuk atlet peringkat institusi pengajian tinggi, dan Sukan Paralimpik untuk Orang Kurang Upaya atau OKU.', 4),
(NULL, 903, 'e9_n3_s1', 'Aku akan padankan enam program itu dengan keterangannya.', 5),
(163, 903, 'e9_n3_s1', 'Teliti kerana ini untuk peperiksaan. Mengapakah sukan dapat memupuk perpaduan?', 6),
(163, 903, 'e9_n3_s2', 'Nota aku menyebut satu temasya yang paling besar dalam negara.', 1),
(162, 903, 'e9_n3_s2', 'Itulah Temasya Sukan Malaysia atau SUKMA, yang dianjurkan secara bergilir-gilir oleh setiap negeri. SUKMA yang pertama diadakan pada tahun 1986.', 2),
(162, 903, 'e9_n3_s2', 'Pelibatan atlet pelbagai kaum yang mewakili setiap negeri berjaya membentuk masyarakat yang harmoni.', 3),
(NULL, 903, 'e9_n3_s2', 'Aku akan baca nota dan pilih temasya yang betul. SUKMA.', 4),
(163, 903, 'e9_n3_s2', 'Jangan teka, baca nota. Jadi apakah yang dibentuk oleh atlet pelbagai kaum yang mewakili negeri?', 5),
(163, 903, 'e9_n3_s3', 'Keratan akhbar tentang Sukan SEA ini jatuh bertaburan. Boleh susun mengikut tahun?', 1),
(162, 903, 'e9_n3_s3', 'Pada tahun 1959 Sukan SEAP, Southeast Asian Peninsular Games, mula dipertandingkan. Pada tahun 1965 Malaysia menjadi tuan rumah kejohanan Sukan SEAP.', 2),
(162, 903, 'e9_n3_s3', 'Pada tahun 1977 Sukan SEAP dikenali sebagai Sukan SEA. Pada tahun 2017 Malaysia menjadi tuan rumah Sukan SEA di Kuala Lumpur.', 3),
(NULL, 903, 'e9_n3_s3', 'Aku akan susun peristiwa itu mengikut tahun.', 4),
(163, 903, 'e9_n3_s3', 'Susun betul-betul dan jangan terbalik. Apakah yang dirapatkan oleh penganjuran Sukan SEA?', 5),
(163, 903, 'e9_n3_s4', 'Gambar Piala Thomas dan Hoki Piala Dunia ini hampir sama. Beza tahun dan stadium?', 1),
(162, 903, 'e9_n3_s4', 'Piala Thomas pada 1970, 1984, 1988 dan 1992 dianjurkan di Stadium Negara, Kuala Lumpur. Piala Thomas 2000 dan 2010 pula di Stadium Putra, Bukit Jalil.', 2),
(162, 903, 'e9_n3_s4', 'Itu bermakna negara kita menganjurkan Piala Thomas sebanyak enam kali.', 3),
(162, 903, 'e9_n3_s4', 'Hoki Piala Dunia 1975 dianjurkan di Stadium Merdeka dengan 12 buah negara. Hoki Piala Dunia 2002 di Stadium Hoki Nasional Bukit Jalil dengan 16 buah negara.', 4),
(NULL, 903, 'e9_n3_s4', 'Aku akan padankan kejohanan dengan stadium dan jumlah negara.', 5),
(163, 903, 'e9_n3_s4', 'Teliti dan jangan campur. Apakah yang dibawa oleh penganjuran kejohanan kepada negara?', 6),
(163, 903, 'e9_n3_s5', 'Tiket-tiket acara antarabangsa ini bercampur dalam kotak. Siapa boleh asingkan?', 1),
(162, 903, 'e9_n3_s5', 'MotoGP dan SBK ialah sukan permotoran antarabangsa yang bermula pada tahun 1991. Le Tour de Langkawi ialah lumba basikal antarabangsa tahunan yang bermula pada tahun 1996.', 2),
(162, 903, 'e9_n3_s5', 'Sukan Komanwel 1998 menjadikan kita negara Asia pertama menjadi tuan rumah. Formula One dianjurkan di Sepang International Circuit sejak tahun 2000.', 3),
(162, 903, 'e9_n3_s5', 'Formula E diadakan di Putrajaya pada tahun 2014. Piala Monsun pula sukan perahu layar di Pulau Duyong, Terengganu sejak tahun 2005.', 4),
(NULL, 903, 'e9_n3_s5', 'Aku akan padankan acara dengan tahun dan tempatnya.', 5),
(163, 903, 'e9_n3_s5', 'Jangan campur tarikh. Apakah faedah acara besar ini kepada negara?', 6),
(163, 903, 'e9_n3_s6', 'Nota Sukan Komanwel 1998 ini aku tampal di halaman paling depan.', 1),
(162, 903, 'e9_n3_s6', 'Malaysia ialah negara Asia pertama menjadi tuan rumah Sukan Komanwel, iaitu pada tahun 1998. Stadium Nasional Bukit Jalil menjadi stadium utama kejohanan.', 2),
(162, 903, 'e9_n3_s6', 'Imej Orang Utan dipilih sebagai maskot dan bunga raya menjadi logo kejohanan.', 3),
(NULL, 903, 'e9_n3_s6', 'Aku akan baca nota dan pilih maskot dan logo yang betul.', 4),
(163, 903, 'e9_n3_s6', 'Jangan buat aku malu di kelas. Jadi apakah yang dipupuk oleh Sukan Komanwel?', 5),
(163, 903, 'e9_n3_s7', 'Guru kata sukan menyatukan kita semua. Tetapi apa peranan diri, masyarakat dan negara?', 1),
(162, 903, 'e9_n3_s7', 'Pada peringkat diri kita mengamalkan sikap saling menghormati antara kaum melalui sukan.', 2),
(162, 903, 'e9_n3_s7', 'Pada peringkat masyarakat, perpaduan dan keharmonian kaum menjamin kesejahteraan masyarakat. Pada peringkat negara, keamanan dan kemakmuran dinikmati bersama apabila perpaduan dikekalkan.', 3),
(NULL, 903, 'e9_n3_s7', 'Aku akan padankan diri, masyarakat dan negara dengan peranan masing-masing.', 4),
(163, 903, 'e9_n3_s7', 'Jangan campur aduk. Mengapa perpaduan perlu dikekalkan supaya sukan terus cemerlang?', 5),
(176, 903, 'e9_n3_s8', 'Aku Sultan Azlan Muhibbuddin Shah, dikenali sebagai Bapa Hoki Malaysia. Aku Presiden Persekutuan Hoki Malaysia dari tahun 1985 hingga 2004.', 1),
(176, 903, 'e9_n3_s8', 'Piala Sultan Azlan Shah ialah kejohanan hoki lapan pasukan terbaik dunia sejak tahun 1992.', 2),
(177, 903, 'e9_n3_s8', 'Aku Dato'' Peter Velappan, Setiausaha Agung Asian Football Confederation dari tahun 1978 hingga 2007.', 3),
(178, 903, 'e9_n3_s8', 'Aku Dato'' Sieh Kok Chi, atlet polo air dan Setiausaha Agung Majlis Olimpik Malaysia dari tahun 1992 hingga 2015.', 4),
(NULL, 903, 'e9_n3_s8', 'Aku akan padankan tokoh dengan sumbangan mereka.', 5),
(163, 903, 'e9_n3_s8', 'Padankan dengan betul. Apakah yang membuktikan kepimpinan sukan mengharumkan nama Malaysia?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (9, 9)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(901, 9, 'Persatuan Badminton Malaysia (BAM) ditubuhkan pada tahun...', '1960', '1952', '1953', '1963', 'A', 'Memajukan badminton.', 'BAM ditubuhkan pada tahun 1960.'),
(902, 9, 'Persatuan Bola Sepak Malaysia (FAM) ditubuhkan pada tahun...', '1960', '1953', '1952', '1963', 'D', 'Menganjurkan Liga Malaysia.', 'FAM ditubuhkan pada tahun 1963.'),
(903, 9, 'Kesatuan Olahraga Amatur Malaysia (KOAM) ditubuhkan pada tahun...', '1953', '1960', '1952', '1963', 'C', 'Kini dikenali sebagai KOM.', 'KOAM ditubuhkan pada tahun 1952 dan kini dikenali sebagai KOM.'),
(904, 9, 'Konfederasi Hoki Malaysia (MHC) ditubuhkan pada tahun...', '1952', '1953', '1960', '1963', 'B', 'Menganjurkan Liga Hoki Kebangsaan.', 'MHC ditubuhkan pada tahun 1953.'),
(905, 9, 'Atlet badminton negara muncul juara Piala Thomas sebanyak...', 'lima kali', 'dua kali', 'tiga kali', 'sepuluh kali', 'A', 'Termasuk pingat Olimpik perak dan gangsa.', 'Atlet negara muncul juara Piala Thomas sebanyak lima kali.'),
(906, 9, 'Pasukan bola sepak negara layak ke Sukan Olimpik pada tahun...', '1960 dan 1964', '1990 dan 1994', '2002 dan 2006', '1972 dan 1980', 'D', 'Munich dan Moscow.', 'Pasukan bola sepak negara layak ke Olimpik Munich 1972 dan Moscow 1980.'),
(907, 9, 'Pasukan bola sepak negara menjuarai Piala Suzuki AFF pada tahun...', '1972', '1980', '2010', '2017', 'C', 'Kejayaan peringkat Asia Tenggara.', 'Pasukan negara menjuarai Piala Suzuki AFF tahun 2010.'),
(908, 9, 'Anugerah PUSKAS FIFA 2016 dimenangi oleh...', 'Lee Chong Wei', 'Mohd Faiz Subri', 'Mokhtar Dahari', 'Safawi Rasid', 'B', 'Pemain Pulau Pinang.', 'Mohd Faiz Subri memenangi PUSKAS FIFA 2016.'),
(909, 9, 'Atlet olahraga negara memenangi emas 100 meter Sukan Asia pada tahun...', '1966 dan 1982', '1960 dan 1964', '1989 dan 2001', '2017 dan 2021', 'A', 'Pelari pecut.', 'Atlet negara memenangi emas 100 meter Sukan Asia pada 1966 dan 1982.'),
(910, 9, 'Malaysia menjadi juara Sukan SEA 2017 dalam olahraga dengan menyumbang...', 'dua pingat emas', 'tiga pingat emas', 'tujuh pingat emas', 'lapan pingat emas', 'D', 'Kuala Lumpur 2017.', 'Atlet olahraga membantu Malaysia menjuarai Sukan SEA 2017 dengan lapan pingat emas.'),
(911, 9, 'Pasukan hoki negara layak ke Hoki Piala Dunia sebanyak...', 'dua kali', 'empat kali', 'lapan kali', 'sepuluh kali', 'C', 'Tempat keempat pada 1975.', 'Pasukan hoki negara layak lapan kali ke Piala Dunia.'),
(912, 9, 'Pasukan hoki negara menjadi naib juara Sukan Komanwel pada tahun...', '1975', '1998', '2002', '2017', 'B', 'Tahun Komanwel di Kuala Lumpur.', 'Pasukan hoki negara menjadi naib juara Sukan Komanwel 1998.'),
(913, 9, 'Lee Chong Wei dinobatkan Anugerah Pemain Lelaki Terbaik BWF sebanyak...', 'lima kali', 'tiga kali', 'dua kali', 'sepuluh kali', 'A', 'Juga nombor satu dunia empat tahun.', 'Lee Chong Wei dinobatkan Pemain Lelaki Terbaik BWF sebanyak lima kali.'),
(914, 9, 'Nicol Ann David memegang gelaran nombor satu dunia skuasy selama...', '10 bulan', '48 bulan', '200 bulan', '108 bulan', 'D', 'Paling lama.', 'Nicol Ann David memegang nombor satu dunia selama 108 bulan.'),
(915, 9, 'Penyumbang pingat gangsa pertama negara di Olimpik London 2012 ialah...', 'Nicol Ann David', 'Nurul Huda', 'Pandelela Rinong', 'Lee Chong Wei', 'C', 'Atlet terjun.', 'Pandelela Rinong ialah penyumbang pingat gangsa pertama di Olimpik London 2012.'),
(916, 9, 'Mohd Azizulhasni Awang digelar...', 'Supermokh', 'The Pocket Rocketman', 'Manusia Terpantas Asia', 'Mr. Asia', 'B', 'Pelumba basikal.', 'Mohd Azizulhasni Awang digelar The Pocket Rocketman.'),
(917, 9, 'Atlet negara yang menjadi ketua pasukan hoki 2000-2006 ialah...', 'S. Kuhan', 'Poon Fook Loke', 'Sarjit Singh', 'Mirnawan Nawawi', 'A', 'Mewakili negara 341 kali.', 'S. Kuhan ialah ketua pasukan hoki negara 2000-2006.'),
(918, 9, 'Nurul Huda Abdullah memenangi lapan pingat emas di Sukan SEA...', 'Bangkok 1985', 'Jakarta 1987', 'Singapura 1993', 'Kuala Lumpur 1989', 'D', 'Dalam renang.', 'Nurul Huda memenangi lapan pingat emas di Sukan SEA Kuala Lumpur 1989.'),
(919, 9, 'Abdul Malek Mohamed Noor mengharumkan nama negara dalam sukan...', 'renang', 'skuasy', 'bina badan', 'lumba basikal', 'C', 'Enam kali Mr. Asia.', 'Abdul Malek memenangi enam kali Mr. Asia dalam sukan bina badan.'),
(920, 9, 'Team Secret MY menduduki tempat ketujuh terbaik dunia dalam...', 'Piala Thomas 2021', 'Kejohanan Final Global PUBG Mobile 2021', 'Sukan Olimpik Tokyo 2020', 'Sukan SEA 2017', 'B', 'Mewakili e-sukan negara.', 'Team Secret MY menduduki tempat ketujuh dunia dalam PMGC 2021.'),
(921, 9, 'Slogan atlet paralimpik negara ialah...', 'Kami Luar Biasa', 'Rakyat Didahulukan', 'Malaysia Boleh', 'Satu Murid Satu Sukan', 'A', 'Menunjukkan kesungguhan.', 'Slogan atlet paralimpik ialah Kami Luar Biasa.'),
(922, 9, 'Atlet yang memecah rekod dunia lompat jauh T20 dengan 7.60 meter ialah...', 'Muhammad Ziyad Zolkefli', 'Mohamad Ridzuan Puzi', 'Bonnie Bunyau Gustin', 'Abdul Latif Romly', 'D', 'Sukan Paralimpik RIO 2016.', 'Abdul Latif Romly mencatat 7.60 meter dalam lompat jauh T20.'),
(923, 9, 'Rancangan Integrasi Murid Untuk Perpaduan (RIMUP) diperkenalkan pada tahun...', '2011', '1986', '2005', '1996', 'C', 'Kerjasama sukan antara sekolah.', 'RIMUP diperkenalkan pada tahun 2005.'),
(924, 9, 'Dasar 1Murid 1Sukan (1M1S) bermula pada tahun...', '2005', '2011', '1996', '2017', 'B', 'Setiap murid melibatkan diri dalam sukan.', '1M1S bermula pada tahun 2011.'),
(925, 9, 'Temasya sukan terbesar dalam negara yang dianjurkan bergilir-gilir oleh setiap negeri ialah...', 'SUKMA', 'MSSM', 'SUKIPT', 'RIMUP', 'A', 'SUKMA pertama pada 1986.', 'SUKMA ialah sukan terbesar dalam negara.'),
(926, 9, 'Sukan Paralimpik ialah temasya sukan bagi...', 'murid sekolah rendah', 'atlet institusi pengajian tinggi', 'pasukan negeri sahaja', 'Orang Kurang Upaya (OKU)', 'D', 'Menyuntik semangat perpaduan.', 'Sukan Paralimpik ialah temasya sukan bagi OKU.'),
(927, 9, 'Sukan SEAP mula dipertandingkan pada tahun...', '1965', '1977', '1959', '2017', 'C', 'Dikenali sebagai Sukan SEA pada 1977.', 'Sukan SEAP mula dipertandingkan pada tahun 1959.'),
(928, 9, 'Piala Thomas dianjurkan di Malaysia sebanyak...', 'dua kali', 'enam kali', 'empat kali', 'lapan kali', 'B', 'Stadium Negara dan Stadium Putra.', 'Piala Thomas dianjurkan di Malaysia sebanyak enam kali.'),
(929, 9, 'Hoki Piala Dunia 2002 dianjurkan di...', 'Stadium Hoki Nasional Bukit Jalil dengan 16 negara', 'Stadium Merdeka dengan 12 negara', 'Stadium Negara dengan 8 negara', 'Stadium Putra dengan 10 negara', 'A', 'Penyertaan terbanyak.', 'Hoki Piala Dunia 2002 diadakan di Bukit Jalil dengan 16 negara.'),
(930, 9, 'Le Tour de Langkawi dianjurkan sebagai acara tahunan bermula pada tahun...', '1991', '2000', '2005', '1996', 'D', 'Menjelajah ke seluruh negara.', 'Le Tour de Langkawi bermula pada tahun 1996.'),
(931, 9, 'Malaysia menjadi negara Asia pertama menjadi tuan rumah Sukan Komanwel pada tahun...', '1975', '2002', '1998', '2017', 'C', 'Maskotnya Orang Utan.', 'Malaysia ialah negara Asia pertama tuan rumah Sukan Komanwel pada 1998.'),
(932, 9, 'Malaysia menjadi tuan rumah Formula One sejak tahun...', '1991', '2000', '1996', '2014', 'B', 'Di Sepang International Circuit.', 'Malaysia menjadi tuan rumah Formula One sejak tahun 2000.'),
(933, 9, 'Sultan Azlan Muhibbuddin Shah dikenali sebagai...', 'Bapa Hoki Malaysia', 'Bapa Kemerdekaan', 'Supermokh', 'Manusia Terpantas Asia', 'A', 'Piala Sultan Azlan Shah sejak 1992.', 'Baginda dikenali sebagai Bapa Hoki Malaysia.'),
(934, 9, 'Mokhtar Dahari digelar...', 'The Pocket Rocketman', 'Manusia Terpantas Asia', 'Bapa Hoki', 'Supermokh', 'D', '167 penampilan, 89 gol.', 'Mokhtar Dahari digelar Supermokh.'),
(935, 9, 'Dr. M. Jegathesan digelar...', 'Supermokh', 'Mr. Asia', 'Manusia Terpantas Asia', 'Bapa Hoki', 'C', 'Tiga emas Sukan Asia Bangkok 1966.', 'Dr. M. Jegathesan digelar Manusia Terpantas Asia.'),
(936, 9, 'Apakah kesan pelibatan pelbagai kaum dalam sukan?', 'Memecahkan perpaduan', 'Memupuk semangat perpaduan', 'Menghalang kejayaan', 'Menjejaskan keharmonian', 'B', 'Sukan alat perpaduan.', 'Pelibatan pelbagai kaum dalam sukan memupuk semangat perpaduan.'),
(937, 9, 'Apakah faedah Le Tour de Langkawi kepada negara?', 'Mempromosikan destinasi pelancongan', 'Menambah kutipan pingat emas', 'Menutup jalan raya', 'Menghentikan pelancongan', 'A', 'Menjelajah ke seluruh negara.', 'Laluan Le Tour de Langkawi membantu mempromosikan destinasi pelancongan.'),
(938, 9, 'Sebuah persatuan sukan menganjurkan liga dan kejohanan kebangsaan setiap tahun. Apakah kesan paling penting kepada negara?', 'Semua pertandingan antarabangsa dihentikan', 'Hanya satu kaum dibenarkan bertanding', 'Atlet tidak lagi perlu berlatih', 'Atlet berbakat dikenal pasti dan dilahirkan untuk mewakili negara', 'D', 'Fikirkan peranan BAM, FAM, KOM dan MHC.', 'Liga dan kejohanan kebangsaan melahirkan atlet berbakat yang kemudian mengharumkan nama negara.'),
(939, 9, 'Lee Chong Wei, Nicol Ann David dan Pandelela Rinong berasal daripada kaum yang berbeza tetapi sama-sama mengharumkan nama negara. Apakah nilai yang paling jelas daripada kejayaan mereka?', 'Kejayaan hanya milik satu kaum', 'Kaum yang berbeza tidak boleh bekerjasama', 'Perpaduan kaum menyumbang kepada kejayaan negara', 'Atlet tidak perlu disokong rakyat', 'C', 'Lihat latar belakang atlet kebanggaan.', 'Atlet pelbagai kaum yang gigih menunjukkan perpaduan kaum menyumbang kepada kejayaan dan kebanggaan negara.'),
(940, 9, 'Seorang murid kerap kalah tetapi tetap berlatih setiap pagi seperti atlet yang diceritakan jurulatihnya. Sifat manakah yang dicontohinya?', 'Sikap mudah berputus asa', 'Kegigihan dan semangat juang', 'Sikap menyalahkan rakan', 'Sikap mengelak latihan', 'B', 'Ingat rahsia kejayaan seorang juara.', 'Kejayaan atlet datang daripada kegigihan, latihan dan semangat juang.'),
(941, 9, 'Bonnie Bunyau Gustin dan Abdul Latif Romly mencipta kejayaan walaupun berdepan cabaran. Apakah pengajaran paling tepat kepada murid?', 'Kesungguhan dan keazaman mampu mengatasi kekurangan diri', 'Orang kurang upaya tidak boleh berjaya dalam sukan', 'Hanya atlet normal layak mewakili negara', 'Slogan Kami Luar Biasa tidak bermakna', 'A', 'Ingat slogan atlet paralimpik negara.', 'Atlet paralimpik membuktikan kesungguhan dan keazaman mampu membawa kejayaan, selari dengan slogan Kami Luar Biasa.'),
(942, 9, 'Pasukan e-sukan Team Secret MY menduduki tempat ketujuh dunia dalam PMGC 2021. Apakah makna kejayaan ini?', 'E-sukan tidak mewakili negara', 'Hanya sukan tradisional boleh berjaya', 'Pasukan itu tidak menyertai pertandingan antarabangsa', 'Bidang sukan baharu juga boleh mengharumkan nama negara', 'D', 'Fikirkan sukan baharu.', 'Kejayaan e-sukan menunjukkan sukan baharu pun mampu mengharumkan nama negara pada peringkat dunia.'),
(943, 9, 'Mengapakah Malaysia dipercayai menjadi tuan rumah Sukan Komanwel 1998 dan Hoki Piala Dunia 2002?', 'Negara tidak mempunyai stadium', 'Hanya kerana tiada negara lain mahu', 'Negara memiliki infrastruktur sukan yang lengkap', 'Kerana atlet negara tidak bertanding', 'C', 'Ingat kad faedah sukan antarabangsa.', 'Kepercayaan sebagai tuan rumah diberikan kerana negara memiliki infrastruktur sukan yang lengkap.'),
(944, 9, 'Penduduk sebuah negeri sibuk bersiap sebagai tuan rumah SUKMA. Apakah kesan tidak langsung kepada ekonomi setempat?', 'Menutup semua perniagaan setempat', 'Menarik pengunjung dan menyumbang kepada pembangunan ekonomi', 'Menghalang pelancong datang', 'Menghentikan pembinaan stadium', 'B', 'Hubungkan pertandingan dengan pengunjung.', 'Penganjuran temasya besar menarik pengunjung dan menyumbang kepada pembangunan ekonomi.'),
(945, 9, 'Dasar 1Murid 1Sukan mewajibkan setiap murid menyertai sekurang-kurangnya satu sukan. Apakah tujuan utamanya?', 'Melibatkan semua murid dan memupuk perpaduan serta gaya hidup sihat', 'Mengurangkan masa belajar semua murid', 'Memilih atlet kebangsaan sahaja', 'Menggantikan semua mata pelajaran', 'A', 'Fikirkan penglibatan semua murid.', 'Setiap murid terlibat dalam sukan supaya perpaduan terpupuk dan semangat kesukanan berkembang.'),
(946, 9, 'Kenapakah penghargaan kepada legenda seperti Mokhtar Dahari dan Dr. M. Jegathesan penting kepada generasi muda?', 'Supaya sukan lama dilupakan', 'Supaya atlet muda berhenti berlatih', 'Kerana mereka tidak lagi berjasa', 'Menjadi inspirasi supaya terus berusaha mengharumkan nama negara', 'D', 'Ingat Supermokh dan Manusia Terpantas Asia.', 'Menghargai atlet terdahulu memberi inspirasi kepada generasi muda untuk terus berusaha.');
